__CR('t:mleval',[{"t":"대표 알고리즘","l":[{"t":"선형·로지스틱 회귀","q":[{"t":"choice","k":"선형회귀 출력","q":"선형회귀(linear regression)가 예측하는 대상은 무엇인가?","o":["연속값(수치)","범주(클래스)","군집 번호","확률 0 또는 1만"],"a":0,"ex":"선형회귀는 집값·기온 같은 연속적인 수치를 예측한다. 범주 예측은 분류(classification)의 영역이다."},{"t":"input","k":"분류 임계값","q":"로지스틱회귀에서 확률을 두 클래스로 나눌 때 가장 흔히 쓰는 기준값(임계값)은?","a":["0.5","0.50"],"ex":"기본 임계값 0.5보다 확률이 크면 양성으로 분류한다. 문제에 따라 조정할 수 있다."}],"th":{"sum":"대표 알고리즘: **선형회귀**는 연속값, **로지스틱회귀**는 확률(분류)을 예측한다. **결정트리**는 규칙 분기, **랜덤포레스트**는 트리들의 앙상블이다.","body":[{"h":"선형·로지스틱 회귀","t":"**선형회귀**는 입력의 가중합으로 **연속적인 수치**를 예측하며 보통 **MSE(평균제곱오차)**를 최소화한다. **로지스틱회귀**는 선형 결과를 **시그모이드(sigmoid)** 함수에 넣어 0~1 확률로 변환해 **분류**에 쓰고, 흔히 **0.5**를 임계값으로 두 클래스를 나눈다."},{"h":"트리와 앙상블","t":"**결정트리**는 특성 조건으로 데이터를 분기하지만 너무 깊어지면 **과적합**된다. **랜덤포레스트**는 여러 결정트리를 서로 다른 데이터·특성으로 학습시켜 다수결·평균으로 합치는 **트리들의 앙상블**로, 과적합을 완화하고 안정성을 높인다. KNN은 거리 기반, k-means는 비지도 군집화다."}],"code":{"c":"# 선형회귀:   ŷ = w·x + b        (연속값, MSE 최소화)\n# 로지스틱:   p = sigmoid(w·x+b)  (0~1 확률)\n#            p ≥ 0.5 → 양성\n# 랜덤포레스트 = 다수 결정트리의 앙상블","cap":"선형=연속값, 로지스틱=확률(분류)"},"key":["선형회귀=연속값 예측, 손실은 MSE","로지스틱회귀=시그모이드로 0~1 확률, 임계값 0.5로 분류","결정트리는 깊어지면 과적합","랜덤포레스트=여러 결정트리의 앙상블"]}},{"t":"트리와 앙상블","q":[{"t":"choice","k":"랜덤포레스트 구성","q":"랜덤포레스트(random forest)는 무엇의 앙상블인가?","o":["여러 결정트리","여러 선형회귀","여러 kNN","여러 SVM"],"a":0,"ex":"랜덤포레스트는 서로 다른 여러 결정트리의 예측을 모아 최종 결정을 내린다."},{"t":"input","k":"앙상블 용어","q":"여러 모델을 결합해 성능을 끌어올리는 기법을 부르는 말은?(한글 또는 영어)","a":["앙상블","ensemble"],"ex":"랜덤포레스트, 부스팅 등이 앙상블(ensemble) 기법에 속한다."}],"th":{"sum":"대표 알고리즘: **선형회귀**는 연속값, **로지스틱회귀**는 확률(분류)을 예측한다. **결정트리**는 규칙 분기, **랜덤포레스트**는 트리들의 앙상블이다.","body":[{"h":"선형·로지스틱 회귀","t":"**선형회귀**는 입력의 가중합으로 **연속적인 수치**를 예측하며 보통 **MSE(평균제곱오차)**를 최소화한다. **로지스틱회귀**는 선형 결과를 **시그모이드(sigmoid)** 함수에 넣어 0~1 확률로 변환해 **분류**에 쓰고, 흔히 **0.5**를 임계값으로 두 클래스를 나눈다."},{"h":"트리와 앙상블","t":"**결정트리**는 특성 조건으로 데이터를 분기하지만 너무 깊어지면 **과적합**된다. **랜덤포레스트**는 여러 결정트리를 서로 다른 데이터·특성으로 학습시켜 다수결·평균으로 합치는 **트리들의 앙상블**로, 과적합을 완화하고 안정성을 높인다. KNN은 거리 기반, k-means는 비지도 군집화다."}],"code":{"c":"# 선형회귀:   ŷ = w·x + b        (연속값, MSE 최소화)\n# 로지스틱:   p = sigmoid(w·x+b)  (0~1 확률)\n#            p ≥ 0.5 → 양성\n# 랜덤포레스트 = 다수 결정트리의 앙상블","cap":"선형=연속값, 로지스틱=확률(분류)"},"key":["선형회귀=연속값 예측, 손실은 MSE","로지스틱회귀=시그모이드로 0~1 확률, 임계값 0.5로 분류","결정트리는 깊어지면 과적합","랜덤포레스트=여러 결정트리의 앙상블"]}},{"t":"거리·비지도·마진","q":[{"t":"choice","k":"작은 k 영향","q":"kNN에서 k가 너무 작을 때 나타나기 쉬운 현상은?","o":["노이즈에 민감해져 과적합 경향","항상 과소적합","거리 계산이 불필요","비지도 학습으로 바뀜"],"a":0,"ex":"k가 작으면 소수 이웃(노이즈 포함)에 좌우되어 결정경계가 들쭉날쭉해진다. k를 키우면 더 매끄러워진다."},{"t":"input","k":"k-means 개수","q":"k-means에서 사용자가 미리 정해야 하는 군집 개수를 나타내는 문자는?","a":["k","K"],"ex":"k-means의 'k'가 바로 만들 군집의 개수이며, 실행 전에 지정해야 한다."}],"th":{"sum":"대표 알고리즘: **선형회귀**는 연속값, **로지스틱회귀**는 확률(분류)을 예측한다. **결정트리**는 규칙 분기, **랜덤포레스트**는 트리들의 앙상블이다.","body":[{"h":"선형·로지스틱 회귀","t":"**선형회귀**는 입력의 가중합으로 **연속적인 수치**를 예측하며 보통 **MSE(평균제곱오차)**를 최소화한다. **로지스틱회귀**는 선형 결과를 **시그모이드(sigmoid)** 함수에 넣어 0~1 확률로 변환해 **분류**에 쓰고, 흔히 **0.5**를 임계값으로 두 클래스를 나눈다."},{"h":"트리와 앙상블","t":"**결정트리**는 특성 조건으로 데이터를 분기하지만 너무 깊어지면 **과적합**된다. **랜덤포레스트**는 여러 결정트리를 서로 다른 데이터·특성으로 학습시켜 다수결·평균으로 합치는 **트리들의 앙상블**로, 과적합을 완화하고 안정성을 높인다. KNN은 거리 기반, k-means는 비지도 군집화다."}],"code":{"c":"# 선형회귀:   ŷ = w·x + b        (연속값, MSE 최소화)\n# 로지스틱:   p = sigmoid(w·x+b)  (0~1 확률)\n#            p ≥ 0.5 → 양성\n# 랜덤포레스트 = 다수 결정트리의 앙상블","cap":"선형=연속값, 로지스틱=확률(분류)"},"key":["선형회귀=연속값 예측, 손실은 MSE","로지스틱회귀=시그모이드로 0~1 확률, 임계값 0.5로 분류","결정트리는 깊어지면 과적합","랜덤포레스트=여러 결정트리의 앙상블"]}}]},{"t":"분류 평가지표","l":[{"t":"혼동행렬 기초","q":[{"t":"choice","k":"FN 정의","q":"실제 양성을 음성으로 놓친 경우는?","o":["FN(거짓 음성)","FP(거짓 양성)","TN(참 음성)","TP(참 양성)"],"a":0,"ex":"False Negative: 양성을 놓친 2종 오류로, 질병 진단 등에서 특히 위험하다."},{"t":"input","k":"정확도 계산","q":"TP=8, FP=2, FN=4, TN=86일 때 정확도(accuracy)를 소수로 구하면?","code":"TP=8  FP=2\nFN=4  TN=86","a":["0.94"],"ex":"accuracy=(TP+TN)/전체=(8+86)/100=94/100=0.94."}],"th":{"sum":"**혼동행렬**의 TP/FP/FN/TN에서 **정밀도**(예측 양성 중 정답)와 **재현율**(실제 양성 중 잡아낸 비율)을 계산한다. 불균형 데이터에선 정확도만 보면 안 된다.","body":[{"h":"혼동행렬","t":"**TP**(실제 양성을 양성으로 맞춤), **FP**(실제 음성을 양성으로 오판=거짓 양성), **FN**(실제 양성을 음성으로 놓침=거짓 음성), **TN**(음성을 음성으로 맞춤). 정확도 = (TP+TN)/전체 — 예로 TP=8,FP=2,FN=4,TN=86이면 (8+86)/100=**0.94**."},{"h":"정밀도·재현율·F1","t":"**정밀도(precision)=TP/(TP+FP)** — 양성이라 예측한 것 중 실제 양성 비율. **재현율(recall)=TP/(TP+FN)** — 실제 양성 중 잡아낸 비율. TP=40,FP=10,FN=20이면 정밀도=40/50=**0.8**, 재현율=40/60≈**0.667**. **F1**은 둘의 조화평균이다. 불균형 데이터에선 정확도가 함정이 되며, **ROC-AUC**로 임계값 전반의 분류 성능을 본다."}],"code":{"c":"# 정확도  = (TP+TN)/전체   = (8+86)/100 = 0.94\n# 정밀도  = TP/(TP+FP)     = 40/50 = 0.8\n# 재현율  = TP/(TP+FN)     = 40/60 ≈ 0.667\n# F1     = 2·P·R/(P+R)  (정밀도·재현율 조화평균)","cap":"정밀도=예측 양성 기준, 재현율=실제 양성 기준"},"key":["TP/FP/FN/TN: FP=거짓 양성, FN=거짓 음성","정밀도=TP/(TP+FP), 재현율=TP/(TP+FN)","F1=정밀도·재현율의 조화평균","불균형 데이터에선 정확도 함정 주의, ROC-AUC 활용"]}},{"t":"정밀도·재현율·F1","q":[{"t":"input","k":"정밀도 계산","q":"TP=40, FP=10, FN=20, TN=30일 때 정밀도(precision)를 소수로 구하면?","code":"TP=40  FP=10\nFN=20  TN=30","a":["0.8","0.80"],"ex":"precision=TP/(TP+FP)=40/(40+10)=40/50=0.8. 양성이라 예측한 것 중 실제 양성 비율이다."},{"t":"input","k":"재현율 계산","q":"같은 행렬(TP=40, FP=10, FN=20, TN=30)에서 재현율(recall)을 소수 셋째 자리까지 구하면?","code":"TP=40  FP=10\nFN=20  TN=30","a":["0.667","0.67","2/3"],"ex":"recall=TP/(TP+FN)=40/(40+20)=40/60≈0.667. 실제 양성 중 맞춘 비율이다."},{"t":"choice","k":"F1 정의","q":"F1 점수는 정밀도와 재현율의 무엇인가?","o":["조화평균(harmonic mean)","산술평균","기하평균","단순 가중합"],"a":0,"ex":"F1=2·P·R/(P+R)로, 두 지표의 조화평균이라 한쪽만 높아선 점수가 오르지 않는다."},{"t":"input","k":"F1 계산","q":"정밀도=0.8, 재현율=0.8일 때 F1 점수를 소수로 구하면?","a":["0.8","0.80"],"ex":"F1=2·0.8·0.8/(0.8+0.8)=1.28/1.6=0.8. 정밀도와 재현율이 같으면 F1도 그 값과 같다."}],"th":{"sum":"**혼동행렬**의 TP/FP/FN/TN에서 **정밀도**(예측 양성 중 정답)와 **재현율**(실제 양성 중 잡아낸 비율)을 계산한다. 불균형 데이터에선 정확도만 보면 안 된다.","body":[{"h":"혼동행렬","t":"**TP**(실제 양성을 양성으로 맞춤), **FP**(실제 음성을 양성으로 오판=거짓 양성), **FN**(실제 양성을 음성으로 놓침=거짓 음성), **TN**(음성을 음성으로 맞춤). 정확도 = (TP+TN)/전체 — 예로 TP=8,FP=2,FN=4,TN=86이면 (8+86)/100=**0.94**."},{"h":"정밀도·재현율·F1","t":"**정밀도(precision)=TP/(TP+FP)** — 양성이라 예측한 것 중 실제 양성 비율. **재현율(recall)=TP/(TP+FN)** — 실제 양성 중 잡아낸 비율. TP=40,FP=10,FN=20이면 정밀도=40/50=**0.8**, 재현율=40/60≈**0.667**. **F1**은 둘의 조화평균이다. 불균형 데이터에선 정확도가 함정이 되며, **ROC-AUC**로 임계값 전반의 분류 성능을 본다."}],"code":{"c":"# 정확도  = (TP+TN)/전체   = (8+86)/100 = 0.94\n# 정밀도  = TP/(TP+FP)     = 40/50 = 0.8\n# 재현율  = TP/(TP+FN)     = 40/60 ≈ 0.667\n# F1     = 2·P·R/(P+R)  (정밀도·재현율 조화평균)","cap":"정밀도=예측 양성 기준, 재현율=실제 양성 기준"},"key":["TP/FP/FN/TN: FP=거짓 양성, FN=거짓 음성","정밀도=TP/(TP+FP), 재현율=TP/(TP+FN)","F1=정밀도·재현율의 조화평균","불균형 데이터에선 정확도 함정 주의, ROC-AUC 활용"]}},{"t":"정확도 함정·ROC-AUC","q":[{"t":"input","k":"불균형 정확도","q":"1000개 중 990개 음성, 10개 양성인데 모두 음성으로 예측하면 정확도는?(소수)","a":["0.99","99%"],"ex":"음성 990개를 맞히므로 accuracy=990/1000=0.99. 하지만 양성 탐지는 완전히 실패한다."},{"t":"choice","k":"AUC 0.5","q":"ROC-AUC 값이 0.5라는 것의 의미는?","o":["무작위 추측 수준의 성능","완벽한 분류","항상 정반대로 맞히는 최악","과적합이 전혀 없음"],"a":0,"ex":"AUC=0.5는 동전 던지기 수준, 1.0은 완벽, 0.5 미만은 무작위보다 못한 상태이다."}],"th":{"sum":"**혼동행렬**의 TP/FP/FN/TN에서 **정밀도**(예측 양성 중 정답)와 **재현율**(실제 양성 중 잡아낸 비율)을 계산한다. 불균형 데이터에선 정확도만 보면 안 된다.","body":[{"h":"혼동행렬","t":"**TP**(실제 양성을 양성으로 맞춤), **FP**(실제 음성을 양성으로 오판=거짓 양성), **FN**(실제 양성을 음성으로 놓침=거짓 음성), **TN**(음성을 음성으로 맞춤). 정확도 = (TP+TN)/전체 — 예로 TP=8,FP=2,FN=4,TN=86이면 (8+86)/100=**0.94**."},{"h":"정밀도·재현율·F1","t":"**정밀도(precision)=TP/(TP+FP)** — 양성이라 예측한 것 중 실제 양성 비율. **재현율(recall)=TP/(TP+FN)** — 실제 양성 중 잡아낸 비율. TP=40,FP=10,FN=20이면 정밀도=40/50=**0.8**, 재현율=40/60≈**0.667**. **F1**은 둘의 조화평균이다. 불균형 데이터에선 정확도가 함정이 되며, **ROC-AUC**로 임계값 전반의 분류 성능을 본다."}],"code":{"c":"# 정확도  = (TP+TN)/전체   = (8+86)/100 = 0.94\n# 정밀도  = TP/(TP+FP)     = 40/50 = 0.8\n# 재현율  = TP/(TP+FN)     = 40/60 ≈ 0.667\n# F1     = 2·P·R/(P+R)  (정밀도·재현율 조화평균)","cap":"정밀도=예측 양성 기준, 재현율=실제 양성 기준"},"key":["TP/FP/FN/TN: FP=거짓 양성, FN=거짓 음성","정밀도=TP/(TP+FP), 재현율=TP/(TP+FN)","F1=정밀도·재현율의 조화평균","불균형 데이터에선 정확도 함정 주의, ROC-AUC 활용"]}}]},{"t":"회귀 평가와 정규화","l":[{"t":"회귀 오차지표","q":[{"t":"choice","k":"이상치 민감","q":"이상치(outlier)에 가장 민감하게 반응하는 오차지표는?","o":["MSE/RMSE(오차를 제곱함)","MAE","R²은 항상 음수","정밀도"],"a":0,"ex":"MSE는 오차를 제곱하므로 큰 오차(이상치)의 영향이 크게 반영된다. MAE는 상대적으로 덜 민감하다."},{"t":"input","k":"MSE 계산","q":"네 예측의 오차(잔차)가 모두 2일 때(2,2,2,2) MSE를 구하면?","a":["4"],"ex":"MSE=(2²+2²+2²+2²)/4=(4+4+4+4)/4=16/4=4. 참고로 RMSE=√4=2이다."}],"th":{"sum":"회귀 오차는 **MAE/MSE/RMSE**로 재고, **R²**는 설명력을 나타낸다. **정규화(L1·L2)**는 가중치에 페널티를 줘 과적합을 억제한다.","body":[{"h":"회귀 오차지표","t":"**MAE**는 잔차 절댓값의 평균, **MSE**는 잔차 제곱의 평균으로 **제곱 때문에 이상치에 가장 민감**하다. **RMSE=√MSE**로 원래 단위를 회복한다. 잔차가 모두 2면 MSE=평균(2²)=**4**, RMSE=2. **R²(결정계수)**가 1에 가까울수록 모델이 데이터 변동을 잘 설명한다는 뜻이다."},{"h":"정규화와 학습","t":"**정규화(regularization)**는 손실에 가중치 크기 페널티를 더해 모델 복잡도를 낮추고 **과적합을 줄인다**. **L1(Lasso)**은 절댓값 페널티로 일부 가중치를 정확히 **0**으로 만들어 특성 선택 효과가 있고, **L2(Ridge)**는 제곱 페널티로 가중치를 전반적으로 작게 줄인다. **경사하강법**은 학습률만큼 손실이 줄어드는 방향으로 파라미터를 갱신한다."}],"code":{"c":"# 잔차 = (2,2,2,2)\n# MAE  = mean(|2|) = 2\n# MSE  = mean(2^2) = 4\n# RMSE = sqrt(4) = 2\n# L1(Lasso): 가중치 일부를 0 → 특성 선택\n# L2(Ridge): 가중치를 전반적으로 축소","cap":"MSE는 이상치에 민감, L1은 희소 해를 만든다"},"key":["MSE/RMSE는 제곱 때문에 이상치에 민감, MAE는 덜 민감","RMSE=√MSE, 잔차 모두 2면 MSE=4","R²이 1에 가까울수록 설명력 높음","정규화는 과적합 억제; L1=Lasso(0 만듦), L2=Ridge(축소)"]}},{"t":"정규화 L1·L2","q":[{"t":"choice","k":"정규화 목적","q":"정규화(regularization)의 주된 목적은?","o":["과적합을 줄여 일반화 성능을 높임","학습률을 강제로 키움","데이터 개수를 늘림","항상 정확도를 100%로 만듦"],"a":0,"ex":"정규화는 큰 가중치에 벌점을 줘 모델을 단순하게 만들고 과적합을 억제한다."},{"t":"input","k":"특성선택 정규화","q":"특성 선택 효과가 있는 정규화는 L1과 L2 중 무엇인가?","a":["L1","Lasso","라쏘"],"ex":"L1(Lasso)이 계수를 0으로 만들어 특성을 걸러낸다. L2(Ridge)는 축소만 한다."},{"t":"choice","k":"정규화 강도","q":"정규화 강도를 크게 높이면 모델은 어떻게 되는가?","o":["단순해져 분산은 줄고 편향은 커짐","항상 과적합이 심해짐","학습이 아예 불가능","항상 정확도가 오름"],"a":0,"ex":"강한 정규화는 계수를 크게 억눌러 모델을 단순화한다. 지나치면 과소적합(편향↑)이 될 수 있다."}],"th":{"sum":"회귀 오차는 **MAE/MSE/RMSE**로 재고, **R²**는 설명력을 나타낸다. **정규화(L1·L2)**는 가중치에 페널티를 줘 과적합을 억제한다.","body":[{"h":"회귀 오차지표","t":"**MAE**는 잔차 절댓값의 평균, **MSE**는 잔차 제곱의 평균으로 **제곱 때문에 이상치에 가장 민감**하다. **RMSE=√MSE**로 원래 단위를 회복한다. 잔차가 모두 2면 MSE=평균(2²)=**4**, RMSE=2. **R²(결정계수)**가 1에 가까울수록 모델이 데이터 변동을 잘 설명한다는 뜻이다."},{"h":"정규화와 학습","t":"**정규화(regularization)**는 손실에 가중치 크기 페널티를 더해 모델 복잡도를 낮추고 **과적합을 줄인다**. **L1(Lasso)**은 절댓값 페널티로 일부 가중치를 정확히 **0**으로 만들어 특성 선택 효과가 있고, **L2(Ridge)**는 제곱 페널티로 가중치를 전반적으로 작게 줄인다. **경사하강법**은 학습률만큼 손실이 줄어드는 방향으로 파라미터를 갱신한다."}],"code":{"c":"# 잔차 = (2,2,2,2)\n# MAE  = mean(|2|) = 2\n# MSE  = mean(2^2) = 4\n# RMSE = sqrt(4) = 2\n# L1(Lasso): 가중치 일부를 0 → 특성 선택\n# L2(Ridge): 가중치를 전반적으로 축소","cap":"MSE는 이상치에 민감, L1은 희소 해를 만든다"},"key":["MSE/RMSE는 제곱 때문에 이상치에 민감, MAE는 덜 민감","RMSE=√MSE, 잔차 모두 2면 MSE=4","R²이 1에 가까울수록 설명력 높음","정규화는 과적합 억제; L1=Lasso(0 만듦), L2=Ridge(축소)"]}},{"t":"하이퍼파라미터·경사하강법","q":[{"t":"choice","k":"하이퍼파라미터","q":"다음 중 하이퍼파라미터(hyperparameter)에 대한 설명으로 옳은 것은?","o":["학습 전에 사람이 정하는 값(학습률·k·트리 깊이 등)","학습으로 자동 추정되는 가중치","모델의 예측 결과값","계산된 손실값"],"a":0,"ex":"학습률, kNN의 k, 트리 깊이처럼 학습 전에 지정하는 설정값이 하이퍼파라미터이다."},{"t":"input","k":"학습률","q":"경사하강법에서 한 번에 얼마나 이동할지 정하는 하이퍼파라미터의 이름은?(한글 또는 영어)","a":["학습률","learning rate","lr"],"ex":"학습률(learning rate)이 각 갱신 단계의 보폭을 결정한다."}],"th":{"sum":"회귀 오차는 **MAE/MSE/RMSE**로 재고, **R²**는 설명력을 나타낸다. **정규화(L1·L2)**는 가중치에 페널티를 줘 과적합을 억제한다.","body":[{"h":"회귀 오차지표","t":"**MAE**는 잔차 절댓값의 평균, **MSE**는 잔차 제곱의 평균으로 **제곱 때문에 이상치에 가장 민감**하다. **RMSE=√MSE**로 원래 단위를 회복한다. 잔차가 모두 2면 MSE=평균(2²)=**4**, RMSE=2. **R²(결정계수)**가 1에 가까울수록 모델이 데이터 변동을 잘 설명한다는 뜻이다."},{"h":"정규화와 학습","t":"**정규화(regularization)**는 손실에 가중치 크기 페널티를 더해 모델 복잡도를 낮추고 **과적합을 줄인다**. **L1(Lasso)**은 절댓값 페널티로 일부 가중치를 정확히 **0**으로 만들어 특성 선택 효과가 있고, **L2(Ridge)**는 제곱 페널티로 가중치를 전반적으로 작게 줄인다. **경사하강법**은 학습률만큼 손실이 줄어드는 방향으로 파라미터를 갱신한다."}],"code":{"c":"# 잔차 = (2,2,2,2)\n# MAE  = mean(|2|) = 2\n# MSE  = mean(2^2) = 4\n# RMSE = sqrt(4) = 2\n# L1(Lasso): 가중치 일부를 0 → 특성 선택\n# L2(Ridge): 가중치를 전반적으로 축소","cap":"MSE는 이상치에 민감, L1은 희소 해를 만든다"},"key":["MSE/RMSE는 제곱 때문에 이상치에 민감, MAE는 덜 민감","RMSE=√MSE, 잔차 모두 2면 MSE=4","R²이 1에 가까울수록 설명력 높음","정규화는 과적합 억제; L1=Lasso(0 만듦), L2=Ridge(축소)"]}}]},{"t":"지표 선택의 함정 (중급)","l":[{"t":"혼동행렬 다시 보기","q":[{"t":"choice","k":"FN 정의","q":"거짓 음성(FN, False Negative)에 해당하는 경우는?","ex":"FN은 놓친 양성이다. 사기 탐지에서는 통과시킨 사기, 의료에서는 놓친 환자에 해당한다.","o":["실제로는 양성인데 모델이 음성으로 예측한 경우","실제로는 음성인데 모델이 양성으로 예측한 경우","실제 양성을 양성으로 맞힌 경우","실제 음성을 음성으로 맞힌 경우"],"a":0},{"t":"choice","k":"정밀도 계산","q":"TP=80, FP=20, FN=40, TN=860일 때 정밀도는?","ex":"정밀도 = TP/(TP+FP) = 80/(80+20) = 0.80. 양성으로 예측한 100건 중 80건이 실제 양성이다.","o":["0.80","0.67","0.50","0.94"],"a":0},{"t":"choice","k":"재현율 계산","q":"TP=80, FP=20, FN=40, TN=860일 때 재현율은 약 얼마인가?","ex":"재현율 = TP/(TP+FN) = 80/(80+40) ≈ 0.67. 실제 양성 120건 중 80건을 잡아냈다.","o":["0.67","0.80","0.94","0.50"],"a":0},{"t":"input","k":"재현율 별칭","q":"재현율(recall)을 의학이나 신호 탐지 분야에서 부르는 다른 이름은? (한글 3글자)","ex":"재현율은 민감도(sensitivity), 진양성률(TPR)과 같은 값이다.","a":["민감도","sensitivity","진양성률","TPR"]}],"th":{"sum":"**정확도는 클래스가 불균형하면 쉽게 사람을 속인다.** 혼동행렬의 네 칸에서 어떤 오류가 더 비싼지를 먼저 정하고 그에 맞는 지표를 골라야 한다.","body":[{"h":"혼동행렬 다시 보기","t":"혼동행렬은 예측과 실제를 교차시킨 네 칸(TP, FP, FN, TN)이다. **정밀도 = TP/(TP+FP)**는 양성이라 예측한 것 중 실제 양성의 비율이고, **재현율 = TP/(TP+FN)**은 실제 양성 중 잡아낸 비율이다. **F1**은 두 값의 조화평균이라 한쪽이 크게 낮으면 F1도 함께 무너진다. 특이도는 TN/(TN+FP)로 실제 음성을 음성으로 맞힌 비율이다."},{"h":"정확도의 함정","t":"양성이 1%뿐인 사기 탐지에서 모든 건을 '정상'이라고만 답해도 정확도는 99%가 된다. 하지만 이 모델의 재현율은 0이고 실무 가치도 0이다. **정확도는 다수 클래스의 성능에 지배되어 소수 클래스의 실패를 감춘다.** 불균형에서는 정밀도·재현율·F1·PR-AUC, 또는 클래스별 재현율의 평균인 균형정확도(balanced accuracy)나 MCC를 함께 본다."},{"h":"무엇을 우선할까","t":"놓쳤을 때의 손실이 큰 문제(암 선별, 사기 탐지)는 **재현율**을 우선하고, 잘못 개입했을 때의 손실이 큰 문제(스팸 격리, 계정 정지)는 **정밀도**를 우선한다. 둘을 하나의 수치로 보고 싶다면 F1을, 어느 한쪽에 더 무게를 두고 싶다면 Fβ를 쓴다. β를 1보다 크게 하면 재현율에, 1보다 작게 하면 정밀도에 더 큰 비중이 실린다."}],"code":{"c":"               예측 양성    예측 음성\n실제 양성         TP          FN\n실제 음성         FP          TN\n\n정밀도 = TP/(TP+FP)      재현율 = TP/(TP+FN)\n특이도 = TN/(TN+FP)      F1 = 2·정밀도·재현율 / (정밀도+재현율)\n\n양성 1% 데이터에서 전부 '음성' 예측 → 정확도 99%, 재현율 0%","cap":"정확도 99%가 아무 일도 하지 않은 모델일 수 있다"},"key":["정밀도는 예측 양성 기준, 재현율은 실제 양성 기준","불균형에서 정확도는 다수 클래스에 지배되어 무의미해진다","F1은 조화평균이라 한쪽이 낮으면 크게 떨어진다","놓치면 손해면 재현율, 잘못 잡으면 손해면 정밀도"]}},{"t":"불균형 데이터와 정확도의 함정","q":[{"t":"choice","k":"균형정확도","q":"균형정확도(balanced accuracy)의 정의로 옳은 것은?","ex":"클래스마다 재현율을 구해 평균내므로 소수 클래스도 다수 클래스와 동등한 비중을 갖는다.","o":["각 클래스별 재현율의 평균","정밀도와 재현율의 평균","전체 정확도에 2를 곱한 값","TP와 TN을 더한 값"],"a":0},{"t":"choice","k":"샘플링 시점","q":"SMOTE 같은 오버샘플링을 교차검증과 함께 쓸 때 반드시 지켜야 할 것은?","ex":"전체에 먼저 적용하면 합성된 샘플의 원본이 검증 폴드에 남아 사실상 답을 본 채 평가하게 되어 성능이 크게 부풀려진다.","o":["각 폴드의 훈련 부분에만 적용하고 검증 폴드에는 적용하지 않는다","전체 데이터에 먼저 적용한 뒤 폴드를 나눈다","검증 폴드와 테스트 세트에도 똑같이 적용한다","적용 시점은 결과에 영향이 없다"],"a":0}],"th":{"sum":"**정확도는 클래스가 불균형하면 쉽게 사람을 속인다.** 혼동행렬의 네 칸에서 어떤 오류가 더 비싼지를 먼저 정하고 그에 맞는 지표를 골라야 한다.","body":[{"h":"혼동행렬 다시 보기","t":"혼동행렬은 예측과 실제를 교차시킨 네 칸(TP, FP, FN, TN)이다. **정밀도 = TP/(TP+FP)**는 양성이라 예측한 것 중 실제 양성의 비율이고, **재현율 = TP/(TP+FN)**은 실제 양성 중 잡아낸 비율이다. **F1**은 두 값의 조화평균이라 한쪽이 크게 낮으면 F1도 함께 무너진다. 특이도는 TN/(TN+FP)로 실제 음성을 음성으로 맞힌 비율이다."},{"h":"정확도의 함정","t":"양성이 1%뿐인 사기 탐지에서 모든 건을 '정상'이라고만 답해도 정확도는 99%가 된다. 하지만 이 모델의 재현율은 0이고 실무 가치도 0이다. **정확도는 다수 클래스의 성능에 지배되어 소수 클래스의 실패를 감춘다.** 불균형에서는 정밀도·재현율·F1·PR-AUC, 또는 클래스별 재현율의 평균인 균형정확도(balanced accuracy)나 MCC를 함께 본다."},{"h":"무엇을 우선할까","t":"놓쳤을 때의 손실이 큰 문제(암 선별, 사기 탐지)는 **재현율**을 우선하고, 잘못 개입했을 때의 손실이 큰 문제(스팸 격리, 계정 정지)는 **정밀도**를 우선한다. 둘을 하나의 수치로 보고 싶다면 F1을, 어느 한쪽에 더 무게를 두고 싶다면 Fβ를 쓴다. β를 1보다 크게 하면 재현율에, 1보다 작게 하면 정밀도에 더 큰 비중이 실린다."}],"code":{"c":"               예측 양성    예측 음성\n실제 양성         TP          FN\n실제 음성         FP          TN\n\n정밀도 = TP/(TP+FP)      재현율 = TP/(TP+FN)\n특이도 = TN/(TN+FP)      F1 = 2·정밀도·재현율 / (정밀도+재현율)\n\n양성 1% 데이터에서 전부 '음성' 예측 → 정확도 99%, 재현율 0%","cap":"정확도 99%가 아무 일도 하지 않은 모델일 수 있다"},"key":["정밀도는 예측 양성 기준, 재현율은 실제 양성 기준","불균형에서 정확도는 다수 클래스에 지배되어 무의미해진다","F1은 조화평균이라 한쪽이 낮으면 크게 떨어진다","놓치면 손해면 재현율, 잘못 잡으면 손해면 정밀도"]}},{"t":"정밀도·재현율 트레이드오프","q":[{"t":"choice","k":"재현율 우선","q":"암 선별 검사처럼 놓치면 치명적인 문제에서 우선적으로 높여야 할 지표는?","ex":"거짓 음성(놓친 환자)의 비용이 압도적으로 크므로 재현율을 우선하고, 늘어난 거짓 양성은 2차 정밀 검사로 걸러낸다.","o":["재현율","정밀도","특이도","정확도"],"a":0},{"t":"choice","k":"정밀도 우선","q":"중요한 메일이 스팸함으로 들어가면 큰 손해인 스팸 필터에서 우선할 지표는?","ex":"여기서는 거짓 양성(정상 메일을 스팸으로 처리)의 비용이 크므로 스팸이라 판단할 때의 신뢰도, 즉 정밀도가 중요하다.","o":["정밀도","재현율","재현율과 특이도의 합","정확도"],"a":0},{"t":"choice","k":"Fβ","q":"재현율을 정밀도보다 더 중요하게 반영하고 싶을 때 사용하는 설정은?","ex":"Fβ에서 β가 클수록 재현율의 비중이 커진다. F2는 재현율 중심, F0.5는 정밀도 중심이다.","o":["β를 1보다 크게 한 Fβ 점수(예: F2)","β를 1보다 작게 한 Fβ 점수(예: F0.5)","F1 점수만 사용해야 한다","정확도를 사용한다"],"a":0}],"th":{"sum":"**정확도는 클래스가 불균형하면 쉽게 사람을 속인다.** 혼동행렬의 네 칸에서 어떤 오류가 더 비싼지를 먼저 정하고 그에 맞는 지표를 골라야 한다.","body":[{"h":"혼동행렬 다시 보기","t":"혼동행렬은 예측과 실제를 교차시킨 네 칸(TP, FP, FN, TN)이다. **정밀도 = TP/(TP+FP)**는 양성이라 예측한 것 중 실제 양성의 비율이고, **재현율 = TP/(TP+FN)**은 실제 양성 중 잡아낸 비율이다. **F1**은 두 값의 조화평균이라 한쪽이 크게 낮으면 F1도 함께 무너진다. 특이도는 TN/(TN+FP)로 실제 음성을 음성으로 맞힌 비율이다."},{"h":"정확도의 함정","t":"양성이 1%뿐인 사기 탐지에서 모든 건을 '정상'이라고만 답해도 정확도는 99%가 된다. 하지만 이 모델의 재현율은 0이고 실무 가치도 0이다. **정확도는 다수 클래스의 성능에 지배되어 소수 클래스의 실패를 감춘다.** 불균형에서는 정밀도·재현율·F1·PR-AUC, 또는 클래스별 재현율의 평균인 균형정확도(balanced accuracy)나 MCC를 함께 본다."},{"h":"무엇을 우선할까","t":"놓쳤을 때의 손실이 큰 문제(암 선별, 사기 탐지)는 **재현율**을 우선하고, 잘못 개입했을 때의 손실이 큰 문제(스팸 격리, 계정 정지)는 **정밀도**를 우선한다. 둘을 하나의 수치로 보고 싶다면 F1을, 어느 한쪽에 더 무게를 두고 싶다면 Fβ를 쓴다. β를 1보다 크게 하면 재현율에, 1보다 작게 하면 정밀도에 더 큰 비중이 실린다."}],"code":{"c":"               예측 양성    예측 음성\n실제 양성         TP          FN\n실제 음성         FP          TN\n\n정밀도 = TP/(TP+FP)      재현율 = TP/(TP+FN)\n특이도 = TN/(TN+FP)      F1 = 2·정밀도·재현율 / (정밀도+재현율)\n\n양성 1% 데이터에서 전부 '음성' 예측 → 정확도 99%, 재현율 0%","cap":"정확도 99%가 아무 일도 하지 않은 모델일 수 있다"},"key":["정밀도는 예측 양성 기준, 재현율은 실제 양성 기준","불균형에서 정확도는 다수 클래스에 지배되어 무의미해진다","F1은 조화평균이라 한쪽이 낮으면 크게 떨어진다","놓치면 손해면 재현율, 잘못 잡으면 손해면 정밀도"]}}]},{"t":"ROC-AUC와 PR-AUC (중급)","l":[{"t":"ROC 곡선 이해하기","q":[{"t":"choice","k":"ROC 축","q":"ROC 곡선의 두 축은 각각 무엇인가?","ex":"y축 정밀도, x축 재현율인 것은 PR 곡선이다.","o":["y축 TPR(재현율), x축 FPR","y축 정밀도, x축 재현율","y축 정확도, x축 임계값","y축 F1, x축 정밀도"],"a":0},{"t":"choice","k":"AUC 0.5","q":"ROC-AUC가 0.5라는 것은 무엇을 뜻하는가?","ex":"AUC 0.5는 대각선 기준선이다. 참고로 항상 같은 클래스로만 예측해도 점수의 순위가 유의미하면 AUC는 0.5보다 클 수 있다.","o":["무작위 추측과 다를 바 없는 순위 성능이다","완벽하게 분류한다","항상 음성으로만 예측한다","정확도가 정확히 50%다"],"a":0}],"th":{"sum":"ROC는 TPR과 FPR을, PR은 정밀도와 재현율을 그린다. **양성이 희귀할수록 ROC-AUC는 낙관적으로 보이고 PR-AUC가 더 정직하다.**","body":[{"h":"ROC 곡선과 AUC","t":"ROC는 임계값을 1에서 0까지 훑으며 x축에 **FPR = FP/(FP+TN)**, y축에 **TPR(재현율)**을 찍은 곡선이다. AUC는 그 아래 면적으로, **무작위로 고른 양성 한 건의 점수가 무작위로 고른 음성 한 건보다 높을 확률**로 해석된다. 무작위 모델은 0.5, 완벽한 순위는 1.0이다. 특정 임계값이 아니라 순위 매기기 능력 전체를 요약한다는 점이 장점이다."},{"h":"PR 곡선이 불균형에 강한 이유","t":"PR 곡선은 x축 재현율, y축 정밀도다. 핵심은 **정밀도가 TN을 전혀 쓰지 않는다**는 점이다. 반면 ROC의 FPR은 분모에 거대한 TN이 들어가므로, 음성이 99%인 데이터에서는 FP가 수백 건 늘어도 FPR이 거의 움직이지 않는다. 그래서 ROC-AUC 0.95인 모델의 PR-AUC가 0.3에 불과한 일이 흔하다. 소수 양성을 찾아내는 것이 목적이라면 PR 곡선이 성능 저하를 훨씬 민감하게 드러낸다."},{"h":"기준선과 선택 기준","t":"**ROC-AUC의 무작위 기준선은 언제나 0.5**지만 **PR-AUC의 기준선은 양성 클래스 비율**과 같다. 그래서 PR-AUC 0.4는 양성 비율 1%에서는 훌륭하고 50%에서는 형편없다. 클래스가 비교적 균형 잡혀 있고 두 오류의 중요도가 비슷하면 ROC-AUC가 무난하고, 희귀 양성 탐지에서는 PR-AUC를 본다. 'ROC-AUC가 항상 더 낫다'는 말은 사실이 아니다."}],"code":{"c":"ROC : x = FPR = FP/(FP+TN)     y = TPR = TP/(TP+FN)   기준선 0.5 (대각선)\nPR  : x = 재현율                y = 정밀도 = TP/(TP+FP) 기준선 = 양성 비율\n\n양성 1% / 음성 99% 인 데이터에서 FP가 200건 늘었을 때\n  FPR 변화 : 200 / 99000  ≈ 0.002  (거의 안 움직임)\n  정밀도 변화 : 분모가 곧바로 커져 뚝 떨어짐\n\n→ 같은 모델인데 ROC-AUC 0.95, PR-AUC 0.30 인 상황이 생긴다","cap":"불균형일수록 PR 곡선이 더 정직하다"},"key":["ROC-AUC = 양성 점수가 음성 점수보다 높을 확률","정밀도는 TN을 쓰지 않아 음성 폭증에 희석되지 않는다","PR-AUC의 기준선은 양성 비율, ROC-AUC 기준선은 항상 0.5","희귀 양성 탐지면 PR-AUC, 균형 데이터면 ROC-AUC"]}},{"t":"PR 곡선과 PR-AUC","q":[{"t":"choice","k":"PR 축","q":"정밀도-재현율(PR) 곡선의 두 축은?","ex":"PR 곡선은 임계값을 바꿔가며 정밀도와 재현율이 어떻게 맞바뀌는지를 보여 준다.","o":["y축 정밀도, x축 재현율","y축 재현율, x축 FPR","y축 정확도, x축 F1","y축 TPR, x축 TNR"],"a":0},{"t":"choice","k":"오개념","q":"다음 중 옳지 않은 설명은?","ex":"두 지표는 보는 관점이 다를 뿐 우열 관계가 아니다. 목적이 희귀 양성 탐지라면 PR-AUC가 더 적합하다.","o":["ROC-AUC는 어떤 상황에서도 PR-AUC보다 항상 우수한 지표다","클래스 불균형이 심하면 ROC-AUC가 실제보다 낙관적으로 보일 수 있다","PR-AUC의 무작위 기준선은 양성 비율에 따라 달라진다","ROC-AUC의 무작위 기준선은 항상 0.5다"],"a":0},{"t":"input","k":"평균 정밀도","q":"사이킷런의 average_precision_score가 계산하는, PR 곡선 아래 면적을 요약한 지표의 한글 이름은? (5글자)","ex":"평균 정밀도(AP)는 재현율 증가분에 정밀도를 가중해 더한 값으로 PR-AUC의 표준적인 계산 방식이다.","a":["평균 정밀도","평균정밀도","average precision","AP"]}],"th":{"sum":"ROC는 TPR과 FPR을, PR은 정밀도와 재현율을 그린다. **양성이 희귀할수록 ROC-AUC는 낙관적으로 보이고 PR-AUC가 더 정직하다.**","body":[{"h":"ROC 곡선과 AUC","t":"ROC는 임계값을 1에서 0까지 훑으며 x축에 **FPR = FP/(FP+TN)**, y축에 **TPR(재현율)**을 찍은 곡선이다. AUC는 그 아래 면적으로, **무작위로 고른 양성 한 건의 점수가 무작위로 고른 음성 한 건보다 높을 확률**로 해석된다. 무작위 모델은 0.5, 완벽한 순위는 1.0이다. 특정 임계값이 아니라 순위 매기기 능력 전체를 요약한다는 점이 장점이다."},{"h":"PR 곡선이 불균형에 강한 이유","t":"PR 곡선은 x축 재현율, y축 정밀도다. 핵심은 **정밀도가 TN을 전혀 쓰지 않는다**는 점이다. 반면 ROC의 FPR은 분모에 거대한 TN이 들어가므로, 음성이 99%인 데이터에서는 FP가 수백 건 늘어도 FPR이 거의 움직이지 않는다. 그래서 ROC-AUC 0.95인 모델의 PR-AUC가 0.3에 불과한 일이 흔하다. 소수 양성을 찾아내는 것이 목적이라면 PR 곡선이 성능 저하를 훨씬 민감하게 드러낸다."},{"h":"기준선과 선택 기준","t":"**ROC-AUC의 무작위 기준선은 언제나 0.5**지만 **PR-AUC의 기준선은 양성 클래스 비율**과 같다. 그래서 PR-AUC 0.4는 양성 비율 1%에서는 훌륭하고 50%에서는 형편없다. 클래스가 비교적 균형 잡혀 있고 두 오류의 중요도가 비슷하면 ROC-AUC가 무난하고, 희귀 양성 탐지에서는 PR-AUC를 본다. 'ROC-AUC가 항상 더 낫다'는 말은 사실이 아니다."}],"code":{"c":"ROC : x = FPR = FP/(FP+TN)     y = TPR = TP/(TP+FN)   기준선 0.5 (대각선)\nPR  : x = 재현율                y = 정밀도 = TP/(TP+FP) 기준선 = 양성 비율\n\n양성 1% / 음성 99% 인 데이터에서 FP가 200건 늘었을 때\n  FPR 변화 : 200 / 99000  ≈ 0.002  (거의 안 움직임)\n  정밀도 변화 : 분모가 곧바로 커져 뚝 떨어짐\n\n→ 같은 모델인데 ROC-AUC 0.95, PR-AUC 0.30 인 상황이 생긴다","cap":"불균형일수록 PR 곡선이 더 정직하다"},"key":["ROC-AUC = 양성 점수가 음성 점수보다 높을 확률","정밀도는 TN을 쓰지 않아 음성 폭증에 희석되지 않는다","PR-AUC의 기준선은 양성 비율, ROC-AUC 기준선은 항상 0.5","희귀 양성 탐지면 PR-AUC, 균형 데이터면 ROC-AUC"]}},{"t":"언제 무엇을 쓸까","q":[{"t":"choice","k":"희귀 양성","q":"전체 거래의 0.2%만 사기인 탐지 모델을 비교할 때 주 지표로 가장 적절한 것은?","ex":"양성이 극히 드물면 ROC-AUC는 모델 간 차이를 잘 드러내지 못한다. PR-AUC가 소수 양성 탐지 성능에 민감하다.","o":["PR-AUC","정확도","ROC-AUC 하나만","특이도"],"a":0},{"t":"choice","k":"균형 데이터","q":"양성과 음성이 각각 절반이고 두 종류 오류의 비용도 비슷한 문제에서 무난한 요약 지표는?","ex":"균형 잡힌 데이터에서는 ROC-AUC가 두 클래스를 대칭적으로 다루므로 해석이 쉽고 안정적이다.","o":["ROC-AUC","양성 비율","특이도 하나만","훈련 정확도"],"a":0},{"t":"choice","k":"모델 비교","q":"두 모델의 ROC-AUC는 0.94로 거의 같은데 PR-AUC는 0.42와 0.18로 크게 다르다. 희귀 양성 탐지가 목적이라면?","ex":"목적에 맞는 지표가 갈라진다면 그 지표를 따라야 한다. ROC-AUC가 비슷한 것은 음성이 압도적이라 차이가 묻힌 결과다.","o":["PR-AUC가 0.42인 모델을 고른다","ROC-AUC 소수점 차이로 고른다","둘 중 아무거나 골라도 무방하다","정확도를 다시 계산해 고른다"],"a":0}],"th":{"sum":"ROC는 TPR과 FPR을, PR은 정밀도와 재현율을 그린다. **양성이 희귀할수록 ROC-AUC는 낙관적으로 보이고 PR-AUC가 더 정직하다.**","body":[{"h":"ROC 곡선과 AUC","t":"ROC는 임계값을 1에서 0까지 훑으며 x축에 **FPR = FP/(FP+TN)**, y축에 **TPR(재현율)**을 찍은 곡선이다. AUC는 그 아래 면적으로, **무작위로 고른 양성 한 건의 점수가 무작위로 고른 음성 한 건보다 높을 확률**로 해석된다. 무작위 모델은 0.5, 완벽한 순위는 1.0이다. 특정 임계값이 아니라 순위 매기기 능력 전체를 요약한다는 점이 장점이다."},{"h":"PR 곡선이 불균형에 강한 이유","t":"PR 곡선은 x축 재현율, y축 정밀도다. 핵심은 **정밀도가 TN을 전혀 쓰지 않는다**는 점이다. 반면 ROC의 FPR은 분모에 거대한 TN이 들어가므로, 음성이 99%인 데이터에서는 FP가 수백 건 늘어도 FPR이 거의 움직이지 않는다. 그래서 ROC-AUC 0.95인 모델의 PR-AUC가 0.3에 불과한 일이 흔하다. 소수 양성을 찾아내는 것이 목적이라면 PR 곡선이 성능 저하를 훨씬 민감하게 드러낸다."},{"h":"기준선과 선택 기준","t":"**ROC-AUC의 무작위 기준선은 언제나 0.5**지만 **PR-AUC의 기준선은 양성 클래스 비율**과 같다. 그래서 PR-AUC 0.4는 양성 비율 1%에서는 훌륭하고 50%에서는 형편없다. 클래스가 비교적 균형 잡혀 있고 두 오류의 중요도가 비슷하면 ROC-AUC가 무난하고, 희귀 양성 탐지에서는 PR-AUC를 본다. 'ROC-AUC가 항상 더 낫다'는 말은 사실이 아니다."}],"code":{"c":"ROC : x = FPR = FP/(FP+TN)     y = TPR = TP/(TP+FN)   기준선 0.5 (대각선)\nPR  : x = 재현율                y = 정밀도 = TP/(TP+FP) 기준선 = 양성 비율\n\n양성 1% / 음성 99% 인 데이터에서 FP가 200건 늘었을 때\n  FPR 변화 : 200 / 99000  ≈ 0.002  (거의 안 움직임)\n  정밀도 변화 : 분모가 곧바로 커져 뚝 떨어짐\n\n→ 같은 모델인데 ROC-AUC 0.95, PR-AUC 0.30 인 상황이 생긴다","cap":"불균형일수록 PR 곡선이 더 정직하다"},"key":["ROC-AUC = 양성 점수가 음성 점수보다 높을 확률","정밀도는 TN을 쓰지 않아 음성 폭증에 희석되지 않는다","PR-AUC의 기준선은 양성 비율, ROC-AUC 기준선은 항상 0.5","희귀 양성 탐지면 PR-AUC, 균형 데이터면 ROC-AUC"]}}]},{"t":"교차검증 설계 (심화)","l":[{"t":"층화와 그룹 분할","q":[{"t":"choice","k":"LOOCV","q":"샘플 수만큼 폴드를 만드는 LOOCV(하나씩 남기기)의 특징은?","ex":"폴드 간 훈련 세트가 거의 동일해 결과들이 강하게 상관되므로, 실무에서는 보통 5-겹이나 10-겹을 쓴다.","o":["훈련 데이터를 거의 다 쓰므로 편향은 작지만 계산 비용이 크고 추정치의 분산이 커질 수 있다","가장 계산이 빠른 방식이다","항상 가장 신뢰할 수 있는 방식이다","회귀 문제에는 쓸 수 없다"],"a":0},{"t":"choice","k":"k 선택","q":"교차검증의 폴드 수 k를 5에서 10으로 늘렸을 때의 변화로 옳은 것은?","ex":"k가 클수록 각 모델이 전체에 가까운 데이터로 학습해 최종 모델의 성능에 가깝게 추정되지만, 학습 횟수가 그만큼 늘어난다.","o":["폴드마다 훈련 데이터가 늘어 성능 추정의 편향은 줄지만 계산 비용이 두 배가 된다","계산 비용이 절반으로 준다","항상 성능 추정이 나빠진다","클래스 불균형이 해소된다"],"a":0}],"th":{"sum":"분할이 잘못되면 어떤 지표도 신뢰할 수 없다. **시계열은 미래 정보를 절대 훈련에 넣지 않고, 그룹이 있는 데이터는 그룹 단위로 나눈다.**","body":[{"h":"기본 분할과 층화","t":"k-겹 교차검증은 데이터를 k개로 나눠 하나씩 돌아가며 검증에 쓴다. 분류에서는 각 폴드의 클래스 비율을 원본과 같게 유지하는 **StratifiedKFold**를 기본으로 쓴다. 층화를 하지 않으면 소수 클래스가 적을 때 어떤 폴드에는 양성이 하나도 없어 지표가 정의되지 않거나 크게 튄다. k를 키우면 폴드마다 훈련 데이터가 많아져 편향은 줄지만 계산 비용과 폴드 간 중복이 늘어난다."},{"h":"시계열 분할","t":"시간 순서가 있는 데이터에 무작위 k-겹을 쓰면 **미래 데이터로 학습해 과거를 예측**하는 셈이 되어 미래 정보 누수가 생긴다. 반드시 훈련 구간이 검증 구간보다 앞서도록 **TimeSeriesSplit** 방식(확장 윈도 또는 슬라이딩 윈도)으로 나눈다. 예측 시점과 레이블이 확정되는 시점 사이에 시차가 있다면 그 사이 구간을 비워 두는 갭(purging)까지 두어야 안전하다."},{"h":"그룹 분할과 중첩 검증","t":"같은 사용자·환자·기기의 기록이 훈련과 검증에 흩어지면 사실상 답을 아는 상태로 평가하게 된다. **GroupKFold**나 StratifiedGroupKFold로 한 그룹이 여러 폴드에 걸치지 않게 한다. 또 하이퍼파라미터 탐색과 최종 평가를 같은 폴드에서 하면 그 폴드에 맞춘 설정이 뽑혀 낙관적 편향이 생기므로, 안쪽 루프에서 튜닝하고 바깥 루프에서 평가하는 **중첩 교차검증**을 쓴다."}],"code":{"c":"무작위 k-겹을 시계열에 쓰면 (누수)\n  [검증][훈련][훈련][훈련]   ← 미래로 과거를 예측하게 됨\n\nTimeSeriesSplit (올바름)\n  훈련 1        | 검증 2\n  훈련 1~2      | 검증 3\n  훈련 1~3      | 검증 4     ← 훈련은 항상 검증보다 과거\n\nStratifiedKFold : 폴드마다 클래스 비율 유지\nGroupKFold      : 같은 group_id는 한 폴드 안에만 존재","cap":"분할 설계가 지표의 신뢰도를 결정한다"},"key":["분류의 기본은 StratifiedKFold","시계열은 훈련 구간이 항상 검증 구간보다 과거여야 한다","같은 사용자·환자 기록이 폴드를 넘으면 그룹 누수","튜닝과 평가를 분리하려면 중첩 교차검증"]}},{"t":"시계열 교차검증","q":[{"t":"choice","k":"홀드아웃 위치","q":"시계열 예측 모델의 최종 홀드아웃 세트는 어디서 떼어내야 하는가?","ex":"운영 환경은 과거로 학습해 미래를 예측하는 상황이므로, 평가도 가장 최근 구간으로 해야 현실과 맞는다.","o":["가장 최근 구간을 통째로 떼어 둔다","전체에서 무작위로 20%를 뽑는다","가장 오래된 구간을 떼어 둔다","각 월에서 균등하게 샘플링한다"],"a":0},{"t":"choice","k":"특성 누수","q":"시계열에서 이동평균 특성을 만들 때 반드시 지켜야 할 원칙은?","ex":"중심 이동평균이나 전체 기간 통계는 미래 값을 포함하므로 명백한 누수다. rolling 계산에서 shift로 현재 값을 제외하는 습관이 필요하다.","o":["현재 시점 이전의 값만 사용하는 과거 윈도로 계산한다","전체 기간의 평균을 사용해 가장 정확한 값을 만든다","앞뒤 3일을 모두 포함하는 중심 이동평균을 쓴다","시계열 특성에는 누수 문제가 없으므로 자유롭게 만든다"],"a":0},{"t":"input","k":"클래스명","q":"사이킷런에서 훈련 구간이 항상 검증 구간보다 앞서도록 시계열 데이터를 분할하는 클래스의 이름은? (영문)","ex":"TimeSeriesSplit은 n_splits와 gap 인자를 지원해 확장 윈도 분할과 갭 설정을 함께 처리한다.","a":["TimeSeriesSplit","timeseriessplit","time series split","TimeSeriesSplit()"]}],"th":{"sum":"분할이 잘못되면 어떤 지표도 신뢰할 수 없다. **시계열은 미래 정보를 절대 훈련에 넣지 않고, 그룹이 있는 데이터는 그룹 단위로 나눈다.**","body":[{"h":"기본 분할과 층화","t":"k-겹 교차검증은 데이터를 k개로 나눠 하나씩 돌아가며 검증에 쓴다. 분류에서는 각 폴드의 클래스 비율을 원본과 같게 유지하는 **StratifiedKFold**를 기본으로 쓴다. 층화를 하지 않으면 소수 클래스가 적을 때 어떤 폴드에는 양성이 하나도 없어 지표가 정의되지 않거나 크게 튄다. k를 키우면 폴드마다 훈련 데이터가 많아져 편향은 줄지만 계산 비용과 폴드 간 중복이 늘어난다."},{"h":"시계열 분할","t":"시간 순서가 있는 데이터에 무작위 k-겹을 쓰면 **미래 데이터로 학습해 과거를 예측**하는 셈이 되어 미래 정보 누수가 생긴다. 반드시 훈련 구간이 검증 구간보다 앞서도록 **TimeSeriesSplit** 방식(확장 윈도 또는 슬라이딩 윈도)으로 나눈다. 예측 시점과 레이블이 확정되는 시점 사이에 시차가 있다면 그 사이 구간을 비워 두는 갭(purging)까지 두어야 안전하다."},{"h":"그룹 분할과 중첩 검증","t":"같은 사용자·환자·기기의 기록이 훈련과 검증에 흩어지면 사실상 답을 아는 상태로 평가하게 된다. **GroupKFold**나 StratifiedGroupKFold로 한 그룹이 여러 폴드에 걸치지 않게 한다. 또 하이퍼파라미터 탐색과 최종 평가를 같은 폴드에서 하면 그 폴드에 맞춘 설정이 뽑혀 낙관적 편향이 생기므로, 안쪽 루프에서 튜닝하고 바깥 루프에서 평가하는 **중첩 교차검증**을 쓴다."}],"code":{"c":"무작위 k-겹을 시계열에 쓰면 (누수)\n  [검증][훈련][훈련][훈련]   ← 미래로 과거를 예측하게 됨\n\nTimeSeriesSplit (올바름)\n  훈련 1        | 검증 2\n  훈련 1~2      | 검증 3\n  훈련 1~3      | 검증 4     ← 훈련은 항상 검증보다 과거\n\nStratifiedKFold : 폴드마다 클래스 비율 유지\nGroupKFold      : 같은 group_id는 한 폴드 안에만 존재","cap":"분할 설계가 지표의 신뢰도를 결정한다"},"key":["분류의 기본은 StratifiedKFold","시계열은 훈련 구간이 항상 검증 구간보다 과거여야 한다","같은 사용자·환자 기록이 폴드를 넘으면 그룹 누수","튜닝과 평가를 분리하려면 중첩 교차검증"]}},{"t":"검증 설계의 함정","q":[{"t":"choice","k":"중첩 검증","q":"중첩 교차검증(nested CV)이 필요한 이유는?","ex":"수십 개 조합 중 검증 점수가 가장 높은 것을 고르면 그 점수 자체에 선택 편향이 섞인다. 바깥 루프가 이를 걸러 준다.","o":["하이퍼파라미터 탐색과 성능 평가를 서로 다른 분할에서 수행해 낙관적 편향을 줄이기 위해","계산 시간을 줄이기 위해","데이터를 늘리기 위해","클래스 불균형을 해소하기 위해"],"a":0},{"t":"choice","k":"최종 모델","q":"교차검증으로 하이퍼파라미터를 고른 뒤 배포용 최종 모델은 어떻게 만드는 것이 일반적인가?","ex":"데이터가 많을수록 성능이 좋아지므로 최종 재학습이 유리하다. 다만 테스트 세트는 최종 평가가 끝난 뒤에만 합칠 수 있다.","o":["선택된 설정으로 훈련+검증 데이터 전체를 다시 학습시킨다","교차검증 중 가장 점수가 높았던 폴드의 모델을 그대로 쓴다","테스트 세트까지 합쳐 다시 학습한 뒤 그 세트로 평가한다","모델을 새로 만들지 않고 평균 점수만 보고한다"],"a":0}],"th":{"sum":"분할이 잘못되면 어떤 지표도 신뢰할 수 없다. **시계열은 미래 정보를 절대 훈련에 넣지 않고, 그룹이 있는 데이터는 그룹 단위로 나눈다.**","body":[{"h":"기본 분할과 층화","t":"k-겹 교차검증은 데이터를 k개로 나눠 하나씩 돌아가며 검증에 쓴다. 분류에서는 각 폴드의 클래스 비율을 원본과 같게 유지하는 **StratifiedKFold**를 기본으로 쓴다. 층화를 하지 않으면 소수 클래스가 적을 때 어떤 폴드에는 양성이 하나도 없어 지표가 정의되지 않거나 크게 튄다. k를 키우면 폴드마다 훈련 데이터가 많아져 편향은 줄지만 계산 비용과 폴드 간 중복이 늘어난다."},{"h":"시계열 분할","t":"시간 순서가 있는 데이터에 무작위 k-겹을 쓰면 **미래 데이터로 학습해 과거를 예측**하는 셈이 되어 미래 정보 누수가 생긴다. 반드시 훈련 구간이 검증 구간보다 앞서도록 **TimeSeriesSplit** 방식(확장 윈도 또는 슬라이딩 윈도)으로 나눈다. 예측 시점과 레이블이 확정되는 시점 사이에 시차가 있다면 그 사이 구간을 비워 두는 갭(purging)까지 두어야 안전하다."},{"h":"그룹 분할과 중첩 검증","t":"같은 사용자·환자·기기의 기록이 훈련과 검증에 흩어지면 사실상 답을 아는 상태로 평가하게 된다. **GroupKFold**나 StratifiedGroupKFold로 한 그룹이 여러 폴드에 걸치지 않게 한다. 또 하이퍼파라미터 탐색과 최종 평가를 같은 폴드에서 하면 그 폴드에 맞춘 설정이 뽑혀 낙관적 편향이 생기므로, 안쪽 루프에서 튜닝하고 바깥 루프에서 평가하는 **중첩 교차검증**을 쓴다."}],"code":{"c":"무작위 k-겹을 시계열에 쓰면 (누수)\n  [검증][훈련][훈련][훈련]   ← 미래로 과거를 예측하게 됨\n\nTimeSeriesSplit (올바름)\n  훈련 1        | 검증 2\n  훈련 1~2      | 검증 3\n  훈련 1~3      | 검증 4     ← 훈련은 항상 검증보다 과거\n\nStratifiedKFold : 폴드마다 클래스 비율 유지\nGroupKFold      : 같은 group_id는 한 폴드 안에만 존재","cap":"분할 설계가 지표의 신뢰도를 결정한다"},"key":["분류의 기본은 StratifiedKFold","시계열은 훈련 구간이 항상 검증 구간보다 과거여야 한다","같은 사용자·환자 기록이 폴드를 넘으면 그룹 누수","튜닝과 평가를 분리하려면 중첩 교차검증"]}}]},{"t":"임계값·비용과 실전 괴리 (심화)","l":[{"t":"임계값 조정","q":[{"t":"choice","k":"임계값 방향","q":"거짓 음성을 줄이는 것이 가장 급한 상황에서 임계값은 어떻게 조정해야 하는가?","ex":"임계값을 낮추면 놓치는 양성은 줄지만 거짓 양성이 늘어난다. 그 대가를 감당할 수 있는지가 판단 기준이다.","o":["낮춘다 - 더 쉽게 양성으로 판정해 재현율을 올린다","높인다 - 더 엄격하게 양성으로 판정한다","0.5로 고정한다","1.0으로 설정한다"],"a":0},{"t":"choice","k":"선택 데이터","q":"최적 임계값은 어떤 데이터에서 골라야 하는가?","ex":"임계값도 하이퍼파라미터다. 테스트 세트로 고르면 그 세트가 더 이상 공정한 최종 평가 기준이 되지 못한다.","o":["검증 세트(또는 교차검증 폴드)","테스트 세트","훈련 세트","실제 운영 트래픽 전체"],"a":0}],"th":{"sum":"모델이 내놓는 것은 점수이고 결정을 만드는 것은 **임계값**이다. 임계값은 정확도가 아니라 **오류의 비즈니스 비용**으로 정하며, 오프라인 지표가 좋아도 실제 성과는 다를 수 있다.","body":[{"h":"임계값은 튜닝 대상이다","t":"0.5는 라이브러리의 기본값일 뿐 최적값이 아니다. 임계값을 낮추면 재현율이 오르고 정밀도가 내려가며, 높이면 반대가 된다. **검증 세트에서 임계값을 훑어 목표(F1 최대, 기대비용 최소, 정밀도 90% 제약 하 재현율 최대 등)를 달성하는 값을 고른 뒤 고정해 테스트에서 확인**한다. 임계값도 검증 데이터로 정하는 튜닝 대상이므로 테스트 세트로 고르면 최종 평가가 오염된다."},{"h":"비용 기반 결정","t":"FN과 FP의 비용이 다르면 **기대비용 = FN수 x 비용(FN) + FP수 x 비용(FP)**를 최소화하는 임계값을 찾는다. 사기 1건을 놓치면 100만원, 정상 거래를 잘못 막으면 1만원이라면 임계값을 크게 낮춰 재현율을 올리는 편이 이득이다. 예측 확률을 비용 계산에 직접 쓰려면 점수가 잘 **보정(calibration)**되어 있어야 하며, 필요하면 Platt scaling이나 isotonic regression으로 보정한다. 심사 인력처럼 처리 용량에 상한이 있다면 상위 N건만 처리하는 제약 하에서 임계값을 정한다."},{"h":"오프라인과 온라인의 괴리","t":"오프라인 지표가 좋아도 실제 성과가 나쁜 원인은 여러 가지다. 시간이 지나며 입력 분포가 변하는 **데이터 드리프트**와 입력-출력 관계 자체가 변하는 **개념 드리프트**, 학습 때와 서빙 때 특성 계산이 어긋나는 **training-serving skew**, 모델의 개입이 이후 학습 데이터를 바꾸는 **피드백 루프**, 그리고 최적화한 대리 지표가 실제 사업 목표와 어긋나는 경우다. 최종 판단은 A/B 테스트 같은 온라인 실험과 지속적인 모니터링으로 한다."}],"code":{"c":"사기 1건 놓침(FN) = 100만원,  정상 거래 오차단(FP) = 1만원\n\n임계값 t    FN 건수   FP 건수    기대비용\n  0.5         40         4      40x100 +   4x1 = 4,004만원\n  0.3         15        30      15x100 +  30x1 = 1,530만원\n  0.1          5       400       5x100 + 400x1 =   900만원\n\n→ 정확도가 최대인 t 가 아니라 기대비용이 최소인 t 를 고른다\n→ 임계값 탐색은 검증 세트에서, 확인은 테스트 세트에서 1회","cap":"임계값은 검증 데이터와 비용표로 정한다"},"key":["임계값 0.5는 기본값일 뿐 최적값이 아니다","FN·FP 비용이 다르면 기대비용 최소 임계값을 찾는다","확률을 비용 계산에 쓰려면 보정 상태를 점검해야 한다","오프라인 개선은 A/B 테스트로 확인해야 실제 성과가 된다"]}},{"t":"비즈니스 비용 최적화","q":[{"t":"choice","k":"기대비용 계산","q":"FN 1건 비용이 100만원, FP 1건 비용이 1만원이다. 임계값 A는 FN 40건·FP 4건, 임계값 B는 FN 15건·FP 30건일 때 기대비용이 더 작은 쪽은?","ex":"A는 40x100 + 4x1 = 4,004만원, B는 15x100 + 30x1 = 1,530만원이다. FN이 훨씬 비싸므로 FN을 줄인 B가 유리하다.","o":["B (1,530만원)","A (4,004만원)","두 임계값의 비용이 같다","비용을 비교할 수 없다"],"a":0},{"t":"choice","k":"비대칭 비용","q":"거짓 음성의 비용이 거짓 양성보다 훨씬 클 때 임계값의 방향은?","ex":"비싼 오류를 줄이는 방향으로 결정 경계를 옮기는 것이 비용 최소화의 기본이다.","o":["기본값보다 낮게 설정해 양성 판정을 늘린다","기본값보다 높게 설정해 양성 판정을 줄인다","비용과 임계값은 관련이 없다","임계값 대신 정확도를 최적화한다"],"a":0},{"t":"input","k":"보정 기법","q":"분류기의 예측 점수를 실제 확률에 가깝게 맞추는 후처리 작업을 무엇이라 하는가? (한글 용어)","ex":"Platt scaling(시그모이드 보정)과 isotonic regression이 대표적인 확률 보정 방법이다.","a":["보정","확률 보정","캘리브레이션","calibration"]}],"th":{"sum":"모델이 내놓는 것은 점수이고 결정을 만드는 것은 **임계값**이다. 임계값은 정확도가 아니라 **오류의 비즈니스 비용**으로 정하며, 오프라인 지표가 좋아도 실제 성과는 다를 수 있다.","body":[{"h":"임계값은 튜닝 대상이다","t":"0.5는 라이브러리의 기본값일 뿐 최적값이 아니다. 임계값을 낮추면 재현율이 오르고 정밀도가 내려가며, 높이면 반대가 된다. **검증 세트에서 임계값을 훑어 목표(F1 최대, 기대비용 최소, 정밀도 90% 제약 하 재현율 최대 등)를 달성하는 값을 고른 뒤 고정해 테스트에서 확인**한다. 임계값도 검증 데이터로 정하는 튜닝 대상이므로 테스트 세트로 고르면 최종 평가가 오염된다."},{"h":"비용 기반 결정","t":"FN과 FP의 비용이 다르면 **기대비용 = FN수 x 비용(FN) + FP수 x 비용(FP)**를 최소화하는 임계값을 찾는다. 사기 1건을 놓치면 100만원, 정상 거래를 잘못 막으면 1만원이라면 임계값을 크게 낮춰 재현율을 올리는 편이 이득이다. 예측 확률을 비용 계산에 직접 쓰려면 점수가 잘 **보정(calibration)**되어 있어야 하며, 필요하면 Platt scaling이나 isotonic regression으로 보정한다. 심사 인력처럼 처리 용량에 상한이 있다면 상위 N건만 처리하는 제약 하에서 임계값을 정한다."},{"h":"오프라인과 온라인의 괴리","t":"오프라인 지표가 좋아도 실제 성과가 나쁜 원인은 여러 가지다. 시간이 지나며 입력 분포가 변하는 **데이터 드리프트**와 입력-출력 관계 자체가 변하는 **개념 드리프트**, 학습 때와 서빙 때 특성 계산이 어긋나는 **training-serving skew**, 모델의 개입이 이후 학습 데이터를 바꾸는 **피드백 루프**, 그리고 최적화한 대리 지표가 실제 사업 목표와 어긋나는 경우다. 최종 판단은 A/B 테스트 같은 온라인 실험과 지속적인 모니터링으로 한다."}],"code":{"c":"사기 1건 놓침(FN) = 100만원,  정상 거래 오차단(FP) = 1만원\n\n임계값 t    FN 건수   FP 건수    기대비용\n  0.5         40         4      40x100 +   4x1 = 4,004만원\n  0.3         15        30      15x100 +  30x1 = 1,530만원\n  0.1          5       400       5x100 + 400x1 =   900만원\n\n→ 정확도가 최대인 t 가 아니라 기대비용이 최소인 t 를 고른다\n→ 임계값 탐색은 검증 세트에서, 확인은 테스트 세트에서 1회","cap":"임계값은 검증 데이터와 비용표로 정한다"},"key":["임계값 0.5는 기본값일 뿐 최적값이 아니다","FN·FP 비용이 다르면 기대비용 최소 임계값을 찾는다","확률을 비용 계산에 쓰려면 보정 상태를 점검해야 한다","오프라인 개선은 A/B 테스트로 확인해야 실제 성과가 된다"]}},{"t":"오프라인 지표와 실제 성능의 괴리","q":[{"t":"choice","k":"스큐","q":"training-serving skew란 무엇인가?","ex":"학습은 배치 파이프라인, 서빙은 실시간 코드로 특성을 계산할 때 자주 생긴다. 특성 계산 로직을 공유하거나 피처 스토어를 쓰면 줄일 수 있다.","o":["학습 시점과 서빙 시점의 특성 계산 로직이나 데이터 소스가 달라 예측이 어긋나는 문제","훈련 데이터가 편향된 문제","모델이 과적합된 문제","GPU와 CPU의 연산 차이"],"a":0},{"t":"choice","k":"온라인 검증","q":"오프라인에서 AUC가 0.02 올랐을 때 배포 판단을 위한 가장 적절한 다음 단계는?","ex":"오프라인 개선이 온라인 성과로 이어진다는 보장은 없다. 통제된 실험이 인과적 확인의 표준이다.","o":["A/B 테스트로 실제 사업 지표에 변화가 있는지 확인한다","오프라인 지표만으로 곧바로 전체 배포한다","테스트 세트로 다시 평가해 확정한다","훈련 데이터를 늘려 AUC를 더 올린다"],"a":0}],"th":{"sum":"모델이 내놓는 것은 점수이고 결정을 만드는 것은 **임계값**이다. 임계값은 정확도가 아니라 **오류의 비즈니스 비용**으로 정하며, 오프라인 지표가 좋아도 실제 성과는 다를 수 있다.","body":[{"h":"임계값은 튜닝 대상이다","t":"0.5는 라이브러리의 기본값일 뿐 최적값이 아니다. 임계값을 낮추면 재현율이 오르고 정밀도가 내려가며, 높이면 반대가 된다. **검증 세트에서 임계값을 훑어 목표(F1 최대, 기대비용 최소, 정밀도 90% 제약 하 재현율 최대 등)를 달성하는 값을 고른 뒤 고정해 테스트에서 확인**한다. 임계값도 검증 데이터로 정하는 튜닝 대상이므로 테스트 세트로 고르면 최종 평가가 오염된다."},{"h":"비용 기반 결정","t":"FN과 FP의 비용이 다르면 **기대비용 = FN수 x 비용(FN) + FP수 x 비용(FP)**를 최소화하는 임계값을 찾는다. 사기 1건을 놓치면 100만원, 정상 거래를 잘못 막으면 1만원이라면 임계값을 크게 낮춰 재현율을 올리는 편이 이득이다. 예측 확률을 비용 계산에 직접 쓰려면 점수가 잘 **보정(calibration)**되어 있어야 하며, 필요하면 Platt scaling이나 isotonic regression으로 보정한다. 심사 인력처럼 처리 용량에 상한이 있다면 상위 N건만 처리하는 제약 하에서 임계값을 정한다."},{"h":"오프라인과 온라인의 괴리","t":"오프라인 지표가 좋아도 실제 성과가 나쁜 원인은 여러 가지다. 시간이 지나며 입력 분포가 변하는 **데이터 드리프트**와 입력-출력 관계 자체가 변하는 **개념 드리프트**, 학습 때와 서빙 때 특성 계산이 어긋나는 **training-serving skew**, 모델의 개입이 이후 학습 데이터를 바꾸는 **피드백 루프**, 그리고 최적화한 대리 지표가 실제 사업 목표와 어긋나는 경우다. 최종 판단은 A/B 테스트 같은 온라인 실험과 지속적인 모니터링으로 한다."}],"code":{"c":"사기 1건 놓침(FN) = 100만원,  정상 거래 오차단(FP) = 1만원\n\n임계값 t    FN 건수   FP 건수    기대비용\n  0.5         40         4      40x100 +   4x1 = 4,004만원\n  0.3         15        30      15x100 +  30x1 = 1,530만원\n  0.1          5       400       5x100 + 400x1 =   900만원\n\n→ 정확도가 최대인 t 가 아니라 기대비용이 최소인 t 를 고른다\n→ 임계값 탐색은 검증 세트에서, 확인은 테스트 세트에서 1회","cap":"임계값은 검증 데이터와 비용표로 정한다"},"key":["임계값 0.5는 기본값일 뿐 최적값이 아니다","FN·FP 비용이 다르면 기대비용 최소 임계값을 찾는다","확률을 비용 계산에 쓰려면 보정 상태를 점검해야 한다","오프라인 개선은 A/B 테스트로 확인해야 실제 성과가 된다"]}}]},{"t":"코드 리뷰 — 결함 찾기","l":[{"t":"코드 리뷰 I","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"# 사기 거래 탐지 (양성 비율 0.2%)\nprint(\"정확도:\", accuracy_score(y, pred))     # 0.998\nprint(\"배포 승인\")","items":[{"txt":"양성이 0.2% 인데 정확도를 본다. 전부 '정상' 으로 예측해도 99.8% 가 나오므로 지표가 모델의 유용성을 전혀 반영하지 않는다.","bad":true},{"txt":"사기 탐지의 목표는 양성을 잡는 것이다. 재현율과 정밀도, 또는 PR-AUC 를 봐야 한다.","bad":true},{"txt":"아무것도 학습하지 않은 다수 클래스 기준선과 비교하지 않았다. 0.998 이 기준선보다 나은지 알 수 없다.","bad":true},{"txt":"정확도 0.998 은 통계적으로 유의하므로 다른 지표는 불필요하다.","bad":false},{"txt":"accuracy_score 의 인자 순서가 (예측, 정답) 이어야 하므로 값이 뒤집혔다.","bad":false},{"txt":"불균형 데이터에서는 어떤 지표도 신뢰할 수 없으므로 평가 자체가 불가능하다.","bad":false}],"ex":"결함 3가지: (1) 불균형에 정확도. (2) 목표에 맞지 않는 지표. (3) 기준선 부재. 극단적 불균형에서는 PR-AUC 와 특정 재현율 구간의 정밀도를 함께 본다. 디스트랙터: 높은 절대값은 유의성과 무관하다. accuracy_score 는 인자 순서에 대칭이다. 불균형에서도 적절한 지표를 고르면 평가할 수 있다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"auc = roc_auc_score(y, prob)\nprint(\"ROC-AUC:\", auc)   # 0.92 → 좋은 모델","items":[{"txt":"심한 불균형에서 ROC-AUC 는 낙관적으로 보인다. 음성이 압도적이면 위양성률 변화가 작게 보여, PR-AUC 와 함께 봐야 한다.","bad":true},{"txt":"AUC 는 임계값 전체를 평균한 값이라 실제 운영 임계값에서의 성능을 말해 주지 않는다.","bad":true},{"txt":"단일 수치만 보고해 신뢰구간이 없다. 표본이 작으면 0.92 의 불확실성이 크다.","bad":true},{"txt":"ROC-AUC 는 0.5 가 무작위이므로 0.92 는 항상 우수하다.","bad":false},{"txt":"roc_auc_score 는 확률이 아니라 예측 클래스를 받아야 하므로 인자가 잘못됐다.","bad":false},{"txt":"AUC 는 클래스 비율에 영향을 받으므로 불균형에서는 계산 자체가 불가능하다.","bad":false}],"ex":"결함 3가지: (1) 불균형에서의 ROC-AUC 낙관성. (2) 운영 임계값 성능 미확인. (3) 불확실성 미보고. 디스트랙터: 절대값만으로 '항상 우수' 를 단정할 수 없다. roc_auc_score 는 점수·확률을 받는다. AUC 는 계산 가능하며 다만 해석에 주의가 필요하다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"scores = cross_val_score(model_a, X, y, cv=5)\nscores_b = cross_val_score(model_b, X, y, cv=5)\nif scores.mean() &gt; scores_b.mean():\n    print(\"A 채택\")","items":[{"txt":"평균만 비교하고 분산을 보지 않는다. 폴드별 차이가 크면 평균 차이는 우연일 수 있다.","bad":true},{"txt":"두 모델이 같은 폴드 분할을 썼는지 보장되지 않는다. cv=5 를 각각 넘기면 셔플 여부·시드에 따라 다른 분할이 될 수 있어 비교가 불공정해진다.","bad":true},{"txt":"통계적 유의성 검정이 없다. 폴드별 점수를 짝지어 비교하는 검정이 필요하다.","bad":true},{"txt":"cross_val_score 는 항상 같은 분할을 쓰므로 공정성 문제가 없다.","bad":false},{"txt":"폴드 5개는 통계 검정에 충분한 표본이므로 검정 없이 평균만으로 결론 낼 수 있다.","bad":false},{"txt":"두 모델의 학습 시간을 비교하지 않은 것이 핵심 결함이다.","bad":false}],"ex":"결함 3가지: (1) 분산 무시. (2) 분할 고정 미보장 — 같은 CV 객체를 넘겨야 한다. (3) 유의성 검정 부재. 디스트랙터: 정수 cv 는 기본적으로 같은 분할을 주지만 셔플·시드를 명시하지 않으면 보장이 약하다는 점이 (2)의 요지다. 폴드 5개는 검정 표본으로 작다. 학습 시간은 별개 논점이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"threshold = 0.5\npred = (prob &gt; threshold).astype(int)\nprint(f1_score(y, pred))","items":[{"txt":"F1 을 보고하면서 임계값을 기본 0.5 로 고정했다. F1 을 최대화하는 임계값은 보통 0.5 가 아니다.","bad":true},{"txt":"임계값을 테스트 세트에서 고르면 낙관적 편향이 생긴다. 검증 세트에서 정해야 한다.","bad":true},{"txt":"F1 은 정밀도와 재현율을 동등하게 취급한다. 오탐과 미탐의 비용이 다르면 가중 F 또는 비용 기반 지표가 맞다.","bad":true},{"txt":"F1 은 임계값과 무관한 지표이므로 임계값 선택이 결과에 영향을 주지 않는다.","bad":false},{"txt":"astype(int) 를 호출하면 불리언이 반전되므로 예측이 뒤집힌다.","bad":false},{"txt":"f1_score 는 다중 클래스에서만 쓸 수 있으므로 이진 분류에서는 오류다.","bad":false}],"ex":"결함 3가지: (1) 기본 임계값. (2) 임계값 선택 세트. (3) 비용 비대칭 미반영. 디스트랙터: F1 은 이진 예측에 대한 지표이므로 임계값에 직접 의존한다. astype(int) 는 True→1 로 변환한다. f1_score 는 이진 분류의 기본 용도다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"model.fit(Xtr, ytr)\nplt.plot(history[\"train_loss\"])\nplt.show()\nprint(\"학습 완료, 손실이 감소했으므로 성공\")","items":[{"txt":"학습 손실만 보고 성공을 판단했다. 학습 손실은 과적합 중에도 계속 감소한다.","bad":true},{"txt":"검증 손실 곡선이 없어 과적합 시점을 알 수 없다.","bad":true},{"txt":"손실은 최적화 지표이고 실제 목표 지표(정확도·AUC 등)와 다를 수 있다. 목표 지표도 함께 추적해야 한다.","bad":true},{"txt":"학습 손실이 감소하면 검증 손실도 반드시 감소하므로 하나만 보면 충분하다.","bad":false},{"txt":"plt.show() 를 호출하면 그래프가 저장되지 않아 기록이 남지 않는 것이 핵심 결함이다.","bad":false},{"txt":"손실 값은 절대적 의미가 없으므로 어떤 곡선도 해석할 수 없다.","bad":false}],"ex":"결함 3가지: (1) 학습 손실만 관찰. (2) 검증 곡선 부재. (3) 목표 지표 미추적. 디스트랙터: 학습 손실 감소와 검증 손실 감소는 별개다. 기록 문제는 부차적이다. 손실 곡선의 추세는 충분히 해석 가능하다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"r2 = r2_score(y, pred)\nprint(\"R²:\", r2)   # 0.85","items":[{"txt":"R² 만으로는 오차의 크기를 알 수 없다. 예측이 실제로 얼마나 벗어나는지 보려면 MAE·RMSE 를 함께 봐야 한다.","bad":true},{"txt":"R² 는 분산이 큰 데이터에서 쉽게 높게 나온다. 목표 변수의 분산이 크면 0.85 가 실용적 정확도를 뜻하지 않는다.","bad":true},{"txt":"잔차의 분포·이분산성·이상치 영향을 확인하지 않았다. 잔차 그림이 필요하다.","bad":true},{"txt":"R² 는 0~1 범위이므로 0.85 는 항상 우수한 성능을 뜻한다.","bad":false},{"txt":"r2_score 는 분류 문제에도 쓸 수 있으므로 문제 유형 확인이 불필요하다.","bad":false},{"txt":"R² 대신 MSE 를 쓰면 단위가 사라져 해석이 불가능해진다.","bad":false}],"ex":"결함 3가지: (1) 오차 크기 미확인. (2) 분산 의존성. (3) 잔차 진단 부재. 디스트랙터: R² 는 음수도 될 수 있고 절대값만으로 우수함을 단정할 수 없다. 분류에는 부적합하다. MSE 는 단위가 제곱이지만 RMSE 로 원래 단위로 돌아온다."}],"th":{"sum":"평가 리뷰의 질문은 세 개다: **이 지표가 목표를 반영하는가 · 이 수치를 믿을 만한가 · 이 세트를 몇 번 들여다봤는가.**","body":[{"h":"지표가 목표를 반영하는가","t":"불균형에서 정확도는 정보가 없고, ROC-AUC 도 낙관적으로 보인다(PR-AUC 를 함께). F1 은 오탐·미탐 비용을 같게 보고, R² 는 오차 크기를 말해 주지 않으며, MAPE 는 0 근처에서 터지고 비대칭이다. 클래스 가중치로 학습하면서 정확도로 평가하면 목표와 평가가 어긋난다. 그리고 어떤 수치든 기준선(다수 클래스·직전 값·인기 순)과 비교하지 않으면 좋은지 알 수 없다."},{"h":"이 수치를 믿을 만한가","t":"단일 수치에는 불확실성이 숨는다. 폴드별 표준편차·신뢰구간·표본 크기를 함께 보고하고, 유효 자릿수를 분산에 맞춘다. 표본 5개의 정밀도, 배치 하나의 손실, 최댓값 보고는 모두 없는 차이를 있는 것처럼 만든다. p 값만으로 결론을 내리면 표본이 큰 쪽이 항상 이긴다 — 효과 크기를 본다."},{"h":"이 세트를 몇 번 들여다봤는가","t":"테스트 세트로 하이퍼파라미터를 고르거나 조기 종료를 하거나 모델을 비교하면, 그 세트는 더 이상 미본 데이터가 아니다. 특성 조합 수천 개에서 최고를 고르면 우연히 높은 조합이 반드시 나온다(다중 비교). 선택은 검증으로, 보고는 테스트로 한 번만. 반복 탐색이 필요하면 중첩 교차검증을 쓴다."},{"h":"평균 하나로는 부족하다","t":"세그먼트별로 나누면 특정 사용자군에서 성능이 훨씬 나쁜 것이 드러난다. 학습·검증 곡선을 함께 그려야 편향과 분산을 구분할 수 있다. 확률을 사용자에게 보여 준다면 보정을 확인해야 하고, 배포 후에는 지연 라벨의 편향과 피드백 루프까지 고려해야 한다."}],"code":{"c":"# 결함: 불균형에 정확도 + 기본 임계값 + 테스트로 튜닝 + 단일 수치\nfor d in [3,5,7]:\n    m = fit(Xtr, ytr, depth=d)\n    a = accuracy_score(yte, m.predict(Xte))     # 양성 0.2% 인데 정확도\n    if a > best: best, bm = a, m\nprint(f\"{best:.4f}\")                             # 낙관적 + 과도한 자릿수\n\n# 고침: 목표 지표 · 검증으로 선택 · 임계값도 검증에서 · 불확실성 보고\ncv = StratifiedKFold(5, shuffle=True, random_state=42)\ngs = GridSearchCV(pipe, grid, cv=cv, scoring=\"average_precision\")\ngs.fit(Xtr, ytr)\ns = cross_val_score(gs.best_estimator_, Xtr, ytr, cv=cv, scoring=\"average_precision\")\nprint(f\"검증 PR-AUC {s.mean():.3f} ± {s.std():.3f}\")\n\npv = gs.predict_proba(Xval)[:,1]                # 임계값은 검증에서 고른다\nth = max(np.linspace(0.01,0.99,99), key=lambda t: fbeta_score(yval, pv>t, beta=2))\n\npt = gs.predict_proba(Xte)[:,1]                 # 테스트는 마지막 한 번\nprint(classification_report(yte, pt>th, digits=3))\nprint(\"기준선(다수):\", average_precision_score(yte, np.zeros_like(pt)))","cap":"선택은 검증에서, 보고는 테스트에서 한 번, 항상 기준선과 함께"},"key":["불균형에 정확도 금지. 목표에 맞는 지표를 먼저 정하고 기준선과 비교한다","임계값 0.5 는 기본값일 뿐이고, 임계값은 검증 세트에서 고른다","테스트 세트로 튜닝·조기 종료·모델 비교를 하면 그 수치는 낙관적이다","평균만 보고하지 않는다 — 표준편차·신뢰구간·표본 크기, 자릿수는 분산에 맞춘다","p 값만으로 결론 내지 않는다. 효과 크기와 다중 비교 보정을 함께 본다","세그먼트별·확률 보정·배포 후 지연 라벨의 편향까지 본다"]}},{"t":"코드 리뷰 II","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"best_score = 0\nfor feats in itertools.combinations(cols, 5):\n    s = cross_val_score(model, X[list(feats)], y, cv=5).mean()\n    if s &gt; best_score: best_score, best_feats = s, feats\nprint(best_score)","items":[{"txt":"수천 개 조합에서 교차검증 최고점을 골라 그 값을 보고했다. 다중 비교 때문에 우연히 높은 조합이 반드시 나온다(선택 편향).","bad":true},{"txt":"특성 선택 자체가 교차검증 밖에서 이루어져, 전체 데이터의 타깃 정보가 선택에 쓰였다.","bad":true},{"txt":"보고 성능은 완전히 분리된 테스트 세트에서 측정해야 한다.","bad":true},{"txt":"교차검증을 쓰면 어떤 탐색을 해도 낙관적 편향이 생기지 않는다.","bad":false},{"txt":"combinations 는 순서를 고려하므로 중복 탐색이 발생하는 것이 핵심 낭비다.","bad":false},{"txt":"특성 5개로 고정하면 탐색 공간이 작아 편향이 없다.","bad":false}],"ex":"결함 3가지: (1) 다중 비교로 인한 선택 편향. (2) 교차검증 밖 특성 선택 — 중첩 교차검증이 필요하다. (3) 보고 세트 분리 부재. 디스트랙터: 교차검증도 여러 번 들여다보면 오염된다. combinations 는 조합이라 중복이 없다. 조합 수가 수천이면 탐색 공간이 작지 않다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"# 학습 데이터 10만, 클래스 A 9만 / B 1만\nmodel.fit(X, y)\nprint(confusion_matrix(yte, model.predict(Xte)))","items":[{"txt":"혼동 행렬을 출력만 하고 해석 기준이 없다. 어떤 셀을 줄이는 것이 목표인지 정의되어야 한다.","bad":true},{"txt":"클래스 불균형을 다루지 않았다. 가중치·리샘플링·임계값 중 무엇도 적용하지 않으면 소수 클래스 재현율이 낮게 나온다.","bad":true},{"txt":"정규화하지 않은 절대 개수만 보면 비율을 놓친다. 클래스별 비율로 함께 봐야 한다.","bad":true},{"txt":"혼동 행렬은 불균형에 영향을 받지 않으므로 균형 처리가 불필요하다.","bad":false},{"txt":"confusion_matrix 는 클래스 순서를 알파벳순으로 정렬하므로 해석에 주의할 필요가 없다.","bad":false},{"txt":"10만 표본이면 어떤 지표도 안정적이므로 소수 클래스 성능을 별도로 볼 필요가 없다.","bad":false}],"ex":"결함 3가지: (1) 목표 셀 미정의. (2) 불균형 미처리. (3) 절대 개수만 관찰. 디스트랙터: 혼동 행렬 자체는 중립이지만 학습 결과가 불균형에 좌우된다. 클래스 순서는 labels 인자로 명시하는 편이 안전하고 '주의 불필요' 는 틀렸다. 소수 클래스가 1만이어도 세부 구간에서는 표본이 적을 수 있다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"p = model.predict_proba(X)[:, 1]\nprint(\"이 고객의 이탈 확률은\", f\"{p[0]:.0%}\")","items":[{"txt":"보정되지 않은 모델의 출력을 확률로 제시했다. 트리 앙상블·SVM 등은 점수가 확률처럼 보이지만 실제 빈도와 어긋난다.","bad":true},{"txt":"보정 곡선(calibration curve)이나 Brier 점수로 확률 품질을 확인하지 않았다.","bad":true},{"txt":"불확실성 없이 단일 값을 사용자에게 제시한다. 표본이 적은 구간에서는 오해를 만든다.","bad":true},{"txt":"predict_proba 는 정의상 확률을 반환하므로 보정이 필요 없다.","bad":false},{"txt":"[:, 1] 은 음성 클래스 확률이므로 값이 뒤집혔다.","bad":false},{"txt":"확률을 백분율로 표시하면 반올림 오차가 생기는 것이 핵심 문제다.","bad":false}],"ex":"결함 3가지: (1) 미보정 확률의 제시. (2) 보정 검증 부재. (3) 불확실성 미표기. 디스트랙터: predict_proba 의 출력은 확률처럼 정규화됐을 뿐 보정을 보장하지 않는다. 인덱스 1 은 양성 클래스다. 반올림은 사소하다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"# A/B 테스트\na_rate = clicks_a / views_a      # 0.052\nb_rate = clicks_b / views_b      # 0.055\nprint(\"B 승리, 전면 적용\")","items":[{"txt":"두 비율의 차이가 통계적으로 유의한지 검정하지 않았다. 표본이 작으면 0.3%p 차이는 우연이다.","bad":true},{"txt":"실험 기간과 표본 크기를 사전에 정하지 않으면, 유리한 시점에 멈추는 편향이 생긴다(peeking).","bad":true},{"txt":"클릭률만 보고 최종 목표 지표(전환·매출·유지)를 확인하지 않았다. 대리 지표만 개선될 수 있다.","bad":true},{"txt":"표본이 충분히 크면 검정 없이 비율 비교만으로 결론을 내릴 수 있다.","bad":false},{"txt":"A/B 테스트에서는 항상 B 를 채택해야 하므로 비교 자체가 불필요하다.","bad":false},{"txt":"클릭률은 비율이므로 신뢰구간을 계산할 수 없다.","bad":false}],"ex":"결함 3가지: (1) 유의성 검정 부재. (2) 사전 설계·조기 종료 편향. (3) 대리 지표 의존. 디스트랙터: 표본 크기와 무관하게 불확실성 정량화가 필요하다. 두 번째는 말이 안 되는 진술이다. 비율에도 신뢰구간을 계산할 수 있다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"model_new = train(latest_data)\nif score(model_new, test) &gt; score(model_old, test):\n    deploy(model_new)","items":[{"txt":"같은 테스트 세트를 반복해서 비교 기준으로 쓴다. 여러 번 쓸수록 그 세트에 과적합된 모델이 선택된다.","bad":true},{"txt":"점수 차이의 크기와 불확실성을 보지 않는다. 0.001 차이로 배포를 결정할 수도 있다.","bad":true},{"txt":"오프라인 지표 개선이 실제 서비스 지표 개선을 뜻하지 않는다. 온라인 검증 단계가 필요하다.","bad":true},{"txt":"테스트 세트는 고정이므로 여러 번 써도 편향이 생기지 않는다.","bad":false},{"txt":"새 데이터로 학습한 모델은 항상 더 좋으므로 비교가 불필요하다.","bad":false},{"txt":"score 함수를 두 번 호출하면 모델 상태가 변해 결과가 달라진다.","bad":false}],"ex":"결함 3가지: (1) 테스트 세트 재사용. (2) 차이의 유의성 미확인. (3) 온라인 검증 부재. 디스트랙터: 고정된 세트를 반복 사용하는 것이 바로 오염이다. 새 데이터가 항상 좋지는 않다. score 는 상태를 바꾸지 않는다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"y_pred = model.predict(X_all)\nmae = mean_absolute_error(y_all, y_pred)\nprint(\"전체 MAE:\", mae)","items":[{"txt":"전체 데이터에 학습 데이터가 포함되어 있으면 낙관적 수치가 된다. 평가 대상은 미본 데이터여야 한다.","bad":true},{"txt":"전체 평균 MAE 하나로는 구간별 성능 차이를 알 수 없다. 값의 크기·세그먼트별로 나눠 봐야 한다.","bad":true},{"txt":"MAE 는 이상치에 둔감해서, 큰 오차가 드물게 발생하는 문제를 가린다. RMSE 나 분위수 오차를 함께 본다.","bad":true},{"txt":"MAE 는 절댓값이므로 부호 정보가 사라져 편향(bias)을 볼 수 없는 것이 유일한 문제다.","bad":false},{"txt":"mean_absolute_error 는 정규화된 값을 반환하므로 단위 해석이 불필요하다.","bad":false},{"txt":"전체 데이터로 평가하면 표본이 커져 추정이 정확해지므로 권장된다.","bad":false}],"ex":"결함 3가지: (1) 학습 데이터 포함 가능성. (2) 세그먼트 분석 부재. (3) 단일 지표의 한계. 디스트랙터: 편향을 못 보는 것은 사실이지만 '유일한 문제' 가 아니다. MAE 는 원래 단위를 유지한다. 표본이 커도 학습 데이터가 섞이면 편향이 커진다."}],"th":{"sum":"평가 리뷰의 질문은 세 개다: **이 지표가 목표를 반영하는가 · 이 수치를 믿을 만한가 · 이 세트를 몇 번 들여다봤는가.**","body":[{"h":"지표가 목표를 반영하는가","t":"불균형에서 정확도는 정보가 없고, ROC-AUC 도 낙관적으로 보인다(PR-AUC 를 함께). F1 은 오탐·미탐 비용을 같게 보고, R² 는 오차 크기를 말해 주지 않으며, MAPE 는 0 근처에서 터지고 비대칭이다. 클래스 가중치로 학습하면서 정확도로 평가하면 목표와 평가가 어긋난다. 그리고 어떤 수치든 기준선(다수 클래스·직전 값·인기 순)과 비교하지 않으면 좋은지 알 수 없다."},{"h":"이 수치를 믿을 만한가","t":"단일 수치에는 불확실성이 숨는다. 폴드별 표준편차·신뢰구간·표본 크기를 함께 보고하고, 유효 자릿수를 분산에 맞춘다. 표본 5개의 정밀도, 배치 하나의 손실, 최댓값 보고는 모두 없는 차이를 있는 것처럼 만든다. p 값만으로 결론을 내리면 표본이 큰 쪽이 항상 이긴다 — 효과 크기를 본다."},{"h":"이 세트를 몇 번 들여다봤는가","t":"테스트 세트로 하이퍼파라미터를 고르거나 조기 종료를 하거나 모델을 비교하면, 그 세트는 더 이상 미본 데이터가 아니다. 특성 조합 수천 개에서 최고를 고르면 우연히 높은 조합이 반드시 나온다(다중 비교). 선택은 검증으로, 보고는 테스트로 한 번만. 반복 탐색이 필요하면 중첩 교차검증을 쓴다."},{"h":"평균 하나로는 부족하다","t":"세그먼트별로 나누면 특정 사용자군에서 성능이 훨씬 나쁜 것이 드러난다. 학습·검증 곡선을 함께 그려야 편향과 분산을 구분할 수 있다. 확률을 사용자에게 보여 준다면 보정을 확인해야 하고, 배포 후에는 지연 라벨의 편향과 피드백 루프까지 고려해야 한다."}],"code":{"c":"# 결함: 불균형에 정확도 + 기본 임계값 + 테스트로 튜닝 + 단일 수치\nfor d in [3,5,7]:\n    m = fit(Xtr, ytr, depth=d)\n    a = accuracy_score(yte, m.predict(Xte))     # 양성 0.2% 인데 정확도\n    if a > best: best, bm = a, m\nprint(f\"{best:.4f}\")                             # 낙관적 + 과도한 자릿수\n\n# 고침: 목표 지표 · 검증으로 선택 · 임계값도 검증에서 · 불확실성 보고\ncv = StratifiedKFold(5, shuffle=True, random_state=42)\ngs = GridSearchCV(pipe, grid, cv=cv, scoring=\"average_precision\")\ngs.fit(Xtr, ytr)\ns = cross_val_score(gs.best_estimator_, Xtr, ytr, cv=cv, scoring=\"average_precision\")\nprint(f\"검증 PR-AUC {s.mean():.3f} ± {s.std():.3f}\")\n\npv = gs.predict_proba(Xval)[:,1]                # 임계값은 검증에서 고른다\nth = max(np.linspace(0.01,0.99,99), key=lambda t: fbeta_score(yval, pv>t, beta=2))\n\npt = gs.predict_proba(Xte)[:,1]                 # 테스트는 마지막 한 번\nprint(classification_report(yte, pt>th, digits=3))\nprint(\"기준선(다수):\", average_precision_score(yte, np.zeros_like(pt)))","cap":"선택은 검증에서, 보고는 테스트에서 한 번, 항상 기준선과 함께"},"key":["불균형에 정확도 금지. 목표에 맞는 지표를 먼저 정하고 기준선과 비교한다","임계값 0.5 는 기본값일 뿐이고, 임계값은 검증 세트에서 고른다","테스트 세트로 튜닝·조기 종료·모델 비교를 하면 그 수치는 낙관적이다","평균만 보고하지 않는다 — 표준편차·신뢰구간·표본 크기, 자릿수는 분산에 맞춘다","p 값만으로 결론 내지 않는다. 효과 크기와 다중 비교 보정을 함께 본다","세그먼트별·확률 보정·배포 후 지연 라벨의 편향까지 본다"]}},{"t":"코드 리뷰 III","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"kf = StratifiedKFold(5)\nfor tr, te in kf.split(X, y):\n    m = clone(model).fit(X[tr], y[tr])\n    scores.append(m.score(X[te], y[te]))\nprint(np.mean(scores))","items":[{"txt":"같은 환자·사용자의 행이 여러 개면 계층화만으로는 그룹 누수를 막지 못한다. StratifiedGroupKFold 가 필요하다.","bad":true},{"txt":"shuffle 과 random_state 를 지정하지 않아 원본 순서에 의존하고 재현 기록이 남지 않는다.","bad":true},{"txt":"평균만 출력하고 표준편차를 함께 보고하지 않는다.","bad":true},{"txt":"clone 을 쓰면 하이퍼파라미터가 초기화되어 매 폴드가 다른 모델이 된다.","bad":false},{"txt":"StratifiedKFold 는 회귀에도 쓸 수 있으므로 문제 유형 확인이 불필요하다.","bad":false},{"txt":"폴드마다 fit 을 다시 호출하면 이전 학습이 누적되어 성능이 부풀려진다.","bad":false}],"ex":"결함 3가지: (1) 그룹 구조 미고려. (2) 셔플·시드 미지정. (3) 분산 미보고. 디스트랙터: clone 은 하이퍼파라미터를 유지하고 학습 상태만 비운다 — 정확한 사용법이다. 계층화는 분류용이다. clone 덕분에 누적되지 않는다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"top_k = np.argsort(-scores)[:10]\nprecision = len(set(top_k) &amp; set(relevant)) / 10\nprint(\"Precision@10:\", precision)","items":[{"txt":"relevant 항목이 10개보다 적을 수 있는데 분모를 10 으로 고정했다. 도달 가능한 최대치가 1 보다 작아져 지표가 왜곡된다.","bad":true},{"txt":"순위 내 위치를 반영하지 않는다. 1위와 10위의 적합 항목을 같게 취급하므로 NDCG·MAP 이 더 적절하다.","bad":true},{"txt":"쿼리 하나의 값만 계산했다. 여러 쿼리에 대해 평균하고 분산을 봐야 한다.","bad":true},{"txt":"argsort 에 음수를 붙이면 오름차순이 되어 순위가 뒤집힌다.","bad":false},{"txt":"Precision@K 는 K 를 크게 하면 항상 증가하므로 K=10 은 부적절하다.","bad":false},{"txt":"집합 교집합을 쓰면 중복 항목이 사라져 값이 부정확해지는 것이 핵심이다.","bad":false}],"ex":"결함 3가지: (1) 분모 고정으로 인한 왜곡 — 적합 항목 수가 적으면 R-precision 이나 Recall@K 를 함께 본다. (2) 순위 정보 미반영. (3) 단일 쿼리 평가. 디스트랙터: -scores 의 argsort 는 내림차순 정렬로 올바르다. Precision@K 는 K 가 커지면 보통 감소한다. 순위 목록에 중복은 없다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"print(\"학습 정확도:\", train_acc)   # 0.99\nprint(\"검증 정확도:\", val_acc)     # 0.71\nprint(\"모델 성능 우수\")","items":[{"txt":"학습과 검증 정확도의 격차가 28%p 다. 명백한 과적합인데 '우수' 로 판단했다.","bad":true},{"txt":"과적합에 대한 대응(규제·데이터 증강·모델 단순화)이 뒤따르지 않는다.","bad":true},{"txt":"검증 정확도 0.71 이 기준선보다 나은지 확인하지 않았다.","bad":true},{"txt":"학습 정확도가 높으면 모델 용량이 충분하다는 뜻이므로 좋은 신호다.","bad":false},{"txt":"검증 정확도는 항상 학습보다 낮으므로 격차 크기는 문제되지 않는다.","bad":false},{"txt":"정확도 대신 손실을 비교해야 하므로 지표 선택이 유일한 결함이다.","bad":false}],"ex":"결함 3가지: (1) 과적합 오판. (2) 대응 부재. (3) 기준선 부재. 디스트랙터: 용량 충분함은 사실이지만 일반화 실패를 상쇄하지 않는다. 격차가 조금 나는 것은 정상이지만 28%p 는 다르다. 지표를 손실로 바꿔도 격차 문제는 그대로다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"X_test_scaled = scaler.fit_transform(X_test)\npred = model.predict(X_test_scaled)","items":[{"txt":"테스트 데이터로 스케일러를 다시 학습했다. 학습 때와 다른 변환이 적용되어 예측이 조용히 틀린다.","bad":true},{"txt":"fit_transform 대신 transform 을 써야 한다. 학습 시 저장한 통계를 그대로 적용하는 것이 원칙이다.","bad":true},{"txt":"테스트 표본이 적으면 통계가 크게 달라져 오차가 더 커진다.","bad":true},{"txt":"StandardScaler 는 각 배치를 독립적으로 정규화하는 것이 정상 동작이므로 문제없다.","bad":false},{"txt":"fit_transform 은 transform 과 동일하게 동작하므로 차이가 없다.","bad":false},{"txt":"테스트 데이터를 스케일링하지 않는 것이 옳으므로 호출 자체가 결함이다.","bad":false}],"ex":"결함 3가지: 전부 같은 뿌리다 — 서빙·평가 시에는 학습에서 얻은 파라미터를 재사용해야 한다. 이 한 글자 차이가 성능 저하의 원인을 찾기 어렵게 만든다. 디스트랙터: 배치별 독립 정규화는 이 스케일러의 동작이 아니다. fit_transform 은 통계를 새로 학습한다. 테스트에도 같은 변환을 적용해야 한다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"for name, m in models.items():\n    m.fit(Xtr, ytr)\n    print(name, m.score(Xte, yte))\n# 가장 높은 모델 선택","items":[{"txt":"여러 모델을 같은 테스트 세트로 비교하고 그중 최고를 골랐다. 비교 횟수만큼 그 세트에 과적합된다.","bad":true},{"txt":"모델별 하이퍼파라미터 탐색 예산이 다르면 비교가 불공정하다. 조건을 맞춰야 한다.","bad":true},{"txt":"점수 차이의 불확실성을 보지 않는다. 교차검증으로 폴드별 분포를 비교해야 한다.","bad":true},{"txt":"서로 다른 모델을 비교할 때는 테스트 세트를 쓰는 것이 표준이므로 문제없다.","bad":false},{"txt":"score 메서드가 모델마다 다른 지표를 반환하므로 비교가 불가능하다.","bad":false},{"txt":"models 를 딕셔너리로 두면 순서가 보장되지 않아 결과가 달라진다.","bad":false}],"ex":"결함 3가지: (1) 테스트 세트 반복 비교. (2) 탐색 예산 불공정. (3) 불확실성 미고려. 디스트랙터: 모델 선택은 검증으로 하고 테스트는 최종 확인용이다. 같은 문제 유형이면 score 는 같은 지표를 쓴다. 파이썬 dict 는 삽입 순서를 유지하며 순서가 결과를 바꾸지도 않는다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"# 시계열 예측 평가\npred = model.predict(X)\nprint(\"MAPE:\", np.mean(np.abs((y - pred) / y)) * 100)","items":[{"txt":"y 에 0 이나 0에 가까운 값이 있으면 나눗셈이 폭발하거나 무한이 된다. MAPE 는 0 근처에서 정의되지 않는다.","bad":true},{"txt":"MAPE 는 과소 예측과 과대 예측을 비대칭으로 벌한다. 예측이 실제보다 작을 때 오차 상한이 100% 로 묶인다.","bad":true},{"txt":"기준선(직전 값 그대로 예측하는 naive forecast)과 비교하지 않았다. 시계열에서는 이 비교가 필수다.","bad":true},{"txt":"MAPE 는 백분율이므로 단위가 다른 시계열 간 비교에 부적합하다는 점이 유일한 문제다.","bad":false},{"txt":"np.mean 은 NaN 을 자동으로 무시하므로 0 나눗셈은 문제되지 않는다.","bad":false},{"txt":"MAPE 대신 MSE 를 쓰면 이상치에 둔감해져 평가가 안정된다.","bad":false}],"ex":"결함 3가지: (1) 0 나눗셈. (2) 비대칭성. (3) naive 기준선 부재. 디스트랙터: 단위 무관 비교는 오히려 MAPE 의 장점이다. np.mean 은 NaN 을 전파한다(nanmean 이 무시한다). MSE 는 이상치에 더 민감하다."}],"th":{"sum":"평가 리뷰의 질문은 세 개다: **이 지표가 목표를 반영하는가 · 이 수치를 믿을 만한가 · 이 세트를 몇 번 들여다봤는가.**","body":[{"h":"지표가 목표를 반영하는가","t":"불균형에서 정확도는 정보가 없고, ROC-AUC 도 낙관적으로 보인다(PR-AUC 를 함께). F1 은 오탐·미탐 비용을 같게 보고, R² 는 오차 크기를 말해 주지 않으며, MAPE 는 0 근처에서 터지고 비대칭이다. 클래스 가중치로 학습하면서 정확도로 평가하면 목표와 평가가 어긋난다. 그리고 어떤 수치든 기준선(다수 클래스·직전 값·인기 순)과 비교하지 않으면 좋은지 알 수 없다."},{"h":"이 수치를 믿을 만한가","t":"단일 수치에는 불확실성이 숨는다. 폴드별 표준편차·신뢰구간·표본 크기를 함께 보고하고, 유효 자릿수를 분산에 맞춘다. 표본 5개의 정밀도, 배치 하나의 손실, 최댓값 보고는 모두 없는 차이를 있는 것처럼 만든다. p 값만으로 결론을 내리면 표본이 큰 쪽이 항상 이긴다 — 효과 크기를 본다."},{"h":"이 세트를 몇 번 들여다봤는가","t":"테스트 세트로 하이퍼파라미터를 고르거나 조기 종료를 하거나 모델을 비교하면, 그 세트는 더 이상 미본 데이터가 아니다. 특성 조합 수천 개에서 최고를 고르면 우연히 높은 조합이 반드시 나온다(다중 비교). 선택은 검증으로, 보고는 테스트로 한 번만. 반복 탐색이 필요하면 중첩 교차검증을 쓴다."},{"h":"평균 하나로는 부족하다","t":"세그먼트별로 나누면 특정 사용자군에서 성능이 훨씬 나쁜 것이 드러난다. 학습·검증 곡선을 함께 그려야 편향과 분산을 구분할 수 있다. 확률을 사용자에게 보여 준다면 보정을 확인해야 하고, 배포 후에는 지연 라벨의 편향과 피드백 루프까지 고려해야 한다."}],"code":{"c":"# 결함: 불균형에 정확도 + 기본 임계값 + 테스트로 튜닝 + 단일 수치\nfor d in [3,5,7]:\n    m = fit(Xtr, ytr, depth=d)\n    a = accuracy_score(yte, m.predict(Xte))     # 양성 0.2% 인데 정확도\n    if a > best: best, bm = a, m\nprint(f\"{best:.4f}\")                             # 낙관적 + 과도한 자릿수\n\n# 고침: 목표 지표 · 검증으로 선택 · 임계값도 검증에서 · 불확실성 보고\ncv = StratifiedKFold(5, shuffle=True, random_state=42)\ngs = GridSearchCV(pipe, grid, cv=cv, scoring=\"average_precision\")\ngs.fit(Xtr, ytr)\ns = cross_val_score(gs.best_estimator_, Xtr, ytr, cv=cv, scoring=\"average_precision\")\nprint(f\"검증 PR-AUC {s.mean():.3f} ± {s.std():.3f}\")\n\npv = gs.predict_proba(Xval)[:,1]                # 임계값은 검증에서 고른다\nth = max(np.linspace(0.01,0.99,99), key=lambda t: fbeta_score(yval, pv>t, beta=2))\n\npt = gs.predict_proba(Xte)[:,1]                 # 테스트는 마지막 한 번\nprint(classification_report(yte, pt>th, digits=3))\nprint(\"기준선(다수):\", average_precision_score(yte, np.zeros_like(pt)))","cap":"선택은 검증에서, 보고는 테스트에서 한 번, 항상 기준선과 함께"},"key":["불균형에 정확도 금지. 목표에 맞는 지표를 먼저 정하고 기준선과 비교한다","임계값 0.5 는 기본값일 뿐이고, 임계값은 검증 세트에서 고른다","테스트 세트로 튜닝·조기 종료·모델 비교를 하면 그 수치는 낙관적이다","평균만 보고하지 않는다 — 표준편차·신뢰구간·표본 크기, 자릿수는 분산에 맞춘다","p 값만으로 결론 내지 않는다. 효과 크기와 다중 비교 보정을 함께 본다","세그먼트별·확률 보정·배포 후 지연 라벨의 편향까지 본다"]}},{"t":"코드 리뷰 IV","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"sample = df.sample(1000)\nacc = evaluate(model, sample)\nprint(\"샘플 평가 정확도:\", acc)","items":[{"txt":"무작위 1,000건만 평가해 신뢰구간이 넓다. 단일 수치를 보고하면 불확실성이 숨는다.","bad":true},{"txt":"층화 없이 샘플링해 소수 클래스가 거의 포함되지 않을 수 있다.","bad":true},{"txt":"샘플 시드를 고정하지 않아 실행마다 결과가 달라지고 비교가 불가능하다.","bad":true},{"txt":"1,000건은 통계적으로 충분한 표본이므로 신뢰구간 계산이 불필요하다.","bad":false},{"txt":"df.sample 은 기본적으로 층화 샘플링을 수행하므로 클래스 비율이 유지된다.","bad":false},{"txt":"전체 평가는 항상 불가능하므로 샘플링 자체가 결함이다.","bad":false}],"ex":"결함 3가지: (1) 불확실성 미보고. (2) 층화 부재. (3) 시드 미고정. 디스트랙터: 충분한 표본 크기는 효과 크기에 따라 다르고, 어차피 구간을 보고하는 편이 정직하다. sample 은 단순 무작위다. 샘플링은 비용 절감을 위한 정당한 선택이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"ensemble = VotingClassifier([(\"a\", m1), (\"b\", m2), (\"c\", m3)])\nensemble.fit(Xtr, ytr)\nprint(ensemble.score(Xte, yte))","items":[{"txt":"개별 모델의 성능을 보고하지 않아 앙상블이 실제로 개선을 주는지 알 수 없다.","bad":true},{"txt":"세 모델의 예측이 서로 상관이 높으면 앙상블 이득이 거의 없다. 다양성을 확인해야 한다.","bad":true},{"txt":"voting 방식(hard/soft)을 명시하지 않았다. 확률 보정 상태가 다른 모델을 soft voting 하면 한 모델이 지배할 수 있다.","bad":true},{"txt":"앙상블은 항상 개별 모델보다 우수하므로 비교가 불필요하다.","bad":false},{"txt":"VotingClassifier 는 가중치를 지정할 수 없으므로 균등 투표만 가능하다.","bad":false},{"txt":"세 모델을 함께 학습하면 학습 시간이 세 배가 되는 것이 핵심 문제다.","bad":false}],"ex":"결함 3가지: (1) 개별 성능 미보고. (2) 다양성 미확인. (3) voting 방식 미지정. 디스트랙터: 앙상블이 항상 낫지는 않다. weights 인자를 지원한다. 학습 시간은 예상된 비용이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"loss = criterion(out, y)\nif loss.item() &lt; best_loss:\n    torch.save(model.state_dict(), \"best.pt\")\n    best_loss = loss.item()","items":[{"txt":"배치 하나의 손실로 최고 모델을 판단한다. 배치별 손실은 요동이 커서 우연히 낮은 배치에서 저장된다.","bad":true},{"txt":"검증 세트 전체에 대한 손실이 아니라 학습 배치 손실을 기준으로 삼았다.","bad":true},{"txt":"옵티마이저 상태와 에포크 번호를 저장하지 않아 학습을 이어갈 수 없다.","bad":true},{"txt":"state_dict 만 저장하면 모델 구조가 사라져 복원이 불가능한 것이 핵심 결함이다.","bad":false},{"txt":"loss.item() 을 호출하면 그래프가 유지되어 메모리가 누수된다.","bad":false},{"txt":"torch.save 는 덮어쓰기를 하지 않으므로 두 번째 저장이 실패한다.","bad":false}],"ex":"결함 3가지: (1) 배치 단위 비교. (2) 학습 손실 기준. (3) 재개 정보 미저장. 디스트랙터: state_dict 저장은 표준이며 구조는 코드로 재현한다. item() 은 오히려 그래프에서 값을 떼어낸다. torch.save 는 덮어쓴다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"scores = [0.81, 0.79, 0.83, 0.80, 0.82]\nprint(f\"성능: {np.mean(scores):.4f}\")   # 0.8100","items":[{"txt":"소수점 넷째 자리까지 보고했지만 폴드 간 표준편차가 0.015 수준이다. 유효하지 않은 정밀도로 차이를 과장한다.","bad":true},{"txt":"표준편차나 신뢰구간을 함께 보고하지 않아 불확실성이 숨는다.","bad":true},{"txt":"평균은 항상 정확한 값이므로 소수점 자리 수는 정보량과 무관하다.","bad":false},{"txt":"표본 5개로는 표준편차를 계산할 수 없으므로 평균만 보고하는 것이 옳다.","bad":false},{"txt":"점수를 하드코딩하면 재현이 불가능한 것이 유일한 문제다.","bad":false},{"txt":"f-string 포매팅은 반올림 오차를 발생시켜 값이 부정확해진다.","bad":false}],"ex":"결함 2가지: (1) 과도한 유효 자릿수 — 0.8100 은 0.810±0.007 정도로 적어야 정직하다. (2) 불확실성 미보고. 이 둘이 모델 비교에서 없는 차이를 있는 것처럼 만든다. 디스트랙터: 자릿수는 정보량에 대한 주장이다. 5개로도 표준편차를 계산한다. 하드코딩은 예시 코드의 성격이고, 포매팅 반올림은 사소하다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"# 추천 시스템 평가\nhits = sum(1 for u in users if rec(u)[0] in clicked[u])\nprint(\"Hit@1:\", hits / len(users))","items":[{"txt":"이미 클릭한 항목을 추천 목록에서 제외하지 않았다면, 사용자가 이미 본 것을 추천해 점수를 얻는 셈이 된다.","bad":true},{"txt":"인기 항목 기준선과 비교하지 않았다. 추천 시스템에서 인기 순 추천은 놀랄 만큼 강한 기준선이다.","bad":true},{"txt":"Hit@1 만 보면 다양성·신규성이 무시된다. 인기 항목만 추천해도 점수가 오른다.","bad":true},{"txt":"Hit@1 은 상위 1개만 보므로 순위 정보를 완전히 반영한다.","bad":false},{"txt":"clicked 를 집합으로 쓰면 순서 정보가 사라져 계산이 불가능하다.","bad":false},{"txt":"사용자 수로 나누면 사용자별 활동량 차이가 보정되지 않는 것이 유일한 문제다.","bad":false}],"ex":"결함 3가지: (1) 이미 소비한 항목 미제외. (2) 인기 기준선 부재. (3) 다양성·신규성 미고려. 디스트랙터: 상위 1개만 보는 것은 순위 정보를 대부분 버리는 것이다. 집합으로도 포함 검사는 된다. 활동량 보정은 부차적이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"if p_value &lt; 0.05:\n    print(\"유의미한 개선\")\nelse:\n    print(\"차이 없음\")","items":[{"txt":"p 값만으로 결론을 내렸다. 효과 크기를 보지 않으면 실용적으로 무의미한 차이도 '유의미' 가 된다(표본이 크면 항상 유의해진다).","bad":true},{"txt":"여러 지표·여러 변형을 함께 검정했다면 다중 비교 보정이 필요하다.","bad":true},{"txt":"'차이 없음' 은 잘못된 해석이다. 유의하지 않다는 것은 차이가 없다는 증거가 아니라 판단할 근거가 부족하다는 뜻이다.","bad":true},{"txt":"p &lt; 0.05 는 95% 확률로 개선이 실제라는 뜻이므로 해석이 정확하다.","bad":false},{"txt":"p 값은 효과 크기를 포함하므로 별도 확인이 불필요하다.","bad":false},{"txt":"검정을 여러 번 하면 검정력이 올라가므로 보정은 불필요하다.","bad":false}],"ex":"결함 3가지: (1) 효과 크기 미확인. (2) 다중 비교 미보정. (3) 귀무가설 채택 오류. 디스트랙터: p 값은 '가설이 참일 확률' 이 아니다. p 값은 효과 크기와 표본 크기가 섞인 값이다. 다중 검정은 위양성을 늘린다."}],"th":{"sum":"평가 리뷰의 질문은 세 개다: **이 지표가 목표를 반영하는가 · 이 수치를 믿을 만한가 · 이 세트를 몇 번 들여다봤는가.**","body":[{"h":"지표가 목표를 반영하는가","t":"불균형에서 정확도는 정보가 없고, ROC-AUC 도 낙관적으로 보인다(PR-AUC 를 함께). F1 은 오탐·미탐 비용을 같게 보고, R² 는 오차 크기를 말해 주지 않으며, MAPE 는 0 근처에서 터지고 비대칭이다. 클래스 가중치로 학습하면서 정확도로 평가하면 목표와 평가가 어긋난다. 그리고 어떤 수치든 기준선(다수 클래스·직전 값·인기 순)과 비교하지 않으면 좋은지 알 수 없다."},{"h":"이 수치를 믿을 만한가","t":"단일 수치에는 불확실성이 숨는다. 폴드별 표준편차·신뢰구간·표본 크기를 함께 보고하고, 유효 자릿수를 분산에 맞춘다. 표본 5개의 정밀도, 배치 하나의 손실, 최댓값 보고는 모두 없는 차이를 있는 것처럼 만든다. p 값만으로 결론을 내리면 표본이 큰 쪽이 항상 이긴다 — 효과 크기를 본다."},{"h":"이 세트를 몇 번 들여다봤는가","t":"테스트 세트로 하이퍼파라미터를 고르거나 조기 종료를 하거나 모델을 비교하면, 그 세트는 더 이상 미본 데이터가 아니다. 특성 조합 수천 개에서 최고를 고르면 우연히 높은 조합이 반드시 나온다(다중 비교). 선택은 검증으로, 보고는 테스트로 한 번만. 반복 탐색이 필요하면 중첩 교차검증을 쓴다."},{"h":"평균 하나로는 부족하다","t":"세그먼트별로 나누면 특정 사용자군에서 성능이 훨씬 나쁜 것이 드러난다. 학습·검증 곡선을 함께 그려야 편향과 분산을 구분할 수 있다. 확률을 사용자에게 보여 준다면 보정을 확인해야 하고, 배포 후에는 지연 라벨의 편향과 피드백 루프까지 고려해야 한다."}],"code":{"c":"# 결함: 불균형에 정확도 + 기본 임계값 + 테스트로 튜닝 + 단일 수치\nfor d in [3,5,7]:\n    m = fit(Xtr, ytr, depth=d)\n    a = accuracy_score(yte, m.predict(Xte))     # 양성 0.2% 인데 정확도\n    if a > best: best, bm = a, m\nprint(f\"{best:.4f}\")                             # 낙관적 + 과도한 자릿수\n\n# 고침: 목표 지표 · 검증으로 선택 · 임계값도 검증에서 · 불확실성 보고\ncv = StratifiedKFold(5, shuffle=True, random_state=42)\ngs = GridSearchCV(pipe, grid, cv=cv, scoring=\"average_precision\")\ngs.fit(Xtr, ytr)\ns = cross_val_score(gs.best_estimator_, Xtr, ytr, cv=cv, scoring=\"average_precision\")\nprint(f\"검증 PR-AUC {s.mean():.3f} ± {s.std():.3f}\")\n\npv = gs.predict_proba(Xval)[:,1]                # 임계값은 검증에서 고른다\nth = max(np.linspace(0.01,0.99,99), key=lambda t: fbeta_score(yval, pv>t, beta=2))\n\npt = gs.predict_proba(Xte)[:,1]                 # 테스트는 마지막 한 번\nprint(classification_report(yte, pt>th, digits=3))\nprint(\"기준선(다수):\", average_precision_score(yte, np.zeros_like(pt)))","cap":"선택은 검증에서, 보고는 테스트에서 한 번, 항상 기준선과 함께"},"key":["불균형에 정확도 금지. 목표에 맞는 지표를 먼저 정하고 기준선과 비교한다","임계값 0.5 는 기본값일 뿐이고, 임계값은 검증 세트에서 고른다","테스트 세트로 튜닝·조기 종료·모델 비교를 하면 그 수치는 낙관적이다","평균만 보고하지 않는다 — 표준편차·신뢰구간·표본 크기, 자릿수는 분산에 맞춘다","p 값만으로 결론 내지 않는다. 효과 크기와 다중 비교 보정을 함께 본다","세그먼트별·확률 보정·배포 후 지연 라벨의 편향까지 본다"]}},{"t":"코드 리뷰 V","q":[{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"train, test = split(data, 0.8)\nprint(\"클래스 분포:\", train.y.mean(), test.y.mean())\n# 0.31, 0.29 → 비슷하므로 진행","items":[{"txt":"타깃 분포만 비교하고 특성 분포를 비교하지 않았다. 특성 분포가 다르면 평가가 편향된다.","bad":true},{"txt":"층화 분할을 명시하지 않아 우연히 비슷해진 것일 수 있다. stratify 로 보장해야 한다.","bad":true},{"txt":"시간·그룹 구조가 있는 데이터인지 확인하지 않았다. 무작위 분할이 적절한지가 먼저다.","bad":true},{"txt":"타깃 분포가 비슷하면 특성 분포도 반드시 비슷하므로 추가 확인이 불필요하다.","bad":false},{"txt":"0.31 과 0.29 의 차이는 통계적으로 유의하므로 재분할이 필수다.","bad":false},{"txt":"분할 비율 0.8 은 너무 커서 테스트 표본이 부족한 것이 핵심 결함이다.","bad":false}],"ex":"결함 3가지: (1) 특성 분포 미확인. (2) 층화 미보장. (3) 분할 방식 적절성 미검토. 디스트랙터: 타깃과 특성 분포는 별개다. 0.02 차이의 유의성은 표본 크기에 따르며 단정할 수 없다. 0.8/0.2 는 표준적이다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"metrics = {}\nfor seg in [\"mobile\", \"desktop\"]:\n    metrics[seg] = auc(y[seg], p[seg])\nprint(metrics)   # mobile 0.71, desktop 0.88","items":[{"txt":"세그먼트 간 성능 격차가 큰데 원인을 파악하지 않고 넘어간다. 특정 사용자군에서 모델이 훨씬 나쁘다는 뜻이다.","bad":true},{"txt":"세그먼트별 표본 크기를 함께 보지 않아, 0.71 이 표본 부족 때문인지 실제 성능 차이인지 알 수 없다.","bad":true},{"txt":"전체 지표만 관리하면 이 격차가 평균에 묻힌다. 세그먼트 지표를 모니터링에 포함해야 한다.","bad":true},{"txt":"세그먼트별로 나누면 표본이 줄어 AUC 계산이 불가능하다.","bad":false},{"txt":"AUC 차이 0.17 은 정상 범위이므로 조치가 필요 없다.","bad":false},{"txt":"두 세그먼트만 나눈 것이 문제이므로 최소 10개 세그먼트가 필요하다.","bad":false}],"ex":"결함 3가지: (1) 격차 원인 미파악. (2) 표본 크기 미확인. (3) 세그먼트 모니터링 부재. 공정성·품질 문제가 여기서 드러난다. 디스트랙터: 세그먼트별 AUC 는 계산 가능하다. 0.17 격차는 큰 차이다. 세그먼트 수는 도메인에 따라 정한다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"learning_curve(model, X, y, train_sizes=[0.1, 0.5, 1.0], cv=3)\nplt.plot(sizes, train_scores.mean(1), label=\"train\")\nplt.show()","items":[{"txt":"학습 곡선의 목적은 학습·검증 점수를 함께 보고 편향과 분산을 구분하는 것인데 검증 점수를 그리지 않았다.","bad":true},{"txt":"점수의 분산(폴드별 편차)을 음영으로 표시하지 않아 곡선 차이가 유의한지 알 수 없다.","bad":true},{"txt":"cv=3 은 폴드가 적어 곡선이 불안정하다.","bad":true},{"txt":"learning_curve 는 학습 점수만 반환하므로 검증 곡선을 그릴 수 없다.","bad":false},{"txt":"train_sizes 를 3개만 쓰면 곡선 형태를 판단할 수 없어 최소 100개가 필요하다.","bad":false},{"txt":"mean(1) 은 잘못된 축이므로 값이 뒤집힌다.","bad":false}],"ex":"결함 3가지: (1) 검증 곡선 누락. (2) 분산 미표시. (3) 폴드 부족. 디스트랙터: learning_curve 는 학습·검증 점수를 모두 반환한다. 3~5개 지점으로도 추세는 읽히고 100개는 과하다. 축 1 은 폴드 축으로 올바르다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"y_true = [0, 1, 1, 0, 1]\ny_pred = [0, 1, 1, 0, 0]\nprint(\"정밀도:\", precision_score(y_true, y_pred))\nprint(\"재현율:\", recall_score(y_true, y_pred))","items":[{"txt":"표본 5개로 계산한 정밀도·재현율은 사실상 아무 정보가 없다. 한 건이 바뀌면 값이 크게 흔들린다.","bad":true},{"txt":"신뢰구간이나 표본 크기를 함께 보고하지 않아 수치가 과신된다.","bad":true},{"txt":"정밀도와 재현율은 비율이므로 표본 크기와 무관하게 정확하다.","bad":false},{"txt":"precision_score 는 다중 클래스 기본값이므로 average 를 지정하지 않으면 오류가 난다.","bad":false},{"txt":"리스트를 넘기면 numpy 배열로 변환되지 않아 계산이 실패한다.","bad":false},{"txt":"두 지표를 함께 보면 F1 이 자동으로 계산되므로 별도 출력이 필요하다.","bad":false}],"ex":"결함 2가지: (1) 표본 부족. (2) 불확실성 미보고. 작은 표본의 지표는 소수 둘째 자리까지 보고할 근거가 없다. 디스트랙터: 비율 추정의 정확도는 표본 크기에 정면으로 의존한다. 이진 라벨이면 average 기본값이 동작한다. 리스트는 자동 변환된다. F1 은 자동 계산되지 않는다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"# 배포 후 성능 측정\nlabels = get_labels_after_30_days()\nacc = accuracy_score(labels, predictions_30_days_ago)\nprint(\"실제 정확도:\", acc)","items":[{"txt":"30일 지연 라벨만 보면 문제를 30일 늦게 발견한다. 즉시 관측 가능한 대리 지표를 함께 둬야 한다.","bad":true},{"txt":"라벨이 붙은 표본만 평가에 들어간다. 라벨이 안 붙는 사례에 편향이 있으면 지표가 왜곡된다.","bad":true},{"txt":"모델의 예측이 사용자 행동에 영향을 준 경우(추천·차단) 라벨 자체가 모델에 의해 오염된다. 피드백 루프를 고려해야 한다.","bad":true},{"txt":"지연 라벨은 정답이므로 어떤 편향도 없다.","bad":false},{"txt":"30일 전 예측과 현재 라벨을 비교하면 시점이 달라 계산이 불가능하다.","bad":false},{"txt":"정확도 대신 AUC 를 쓰면 지연 문제가 해결된다.","bad":false}],"ex":"결함 3가지: (1) 지연 라벨만 의존. (2) 라벨 획득 편향. (3) 피드백 루프 오염. 디스트랙터: 지연 라벨도 선택 편향과 오염을 겪는다. 예측과 라벨을 시점으로 짝지으면 비교할 수 있다. 지표 교체는 지연을 해결하지 못한다."},{"t":"review","k":"코드 리뷰","cat":"review","q":"이 코드의 결함을 모두 고르세요","code":"def evaluate(model, X, y):\n    return {\"acc\": accuracy_score(y, model.predict(X))}\n\nreport(evaluate(model, Xte, yte))","items":[{"txt":"평가 함수가 단일 지표만 반환한다. 문제 유형과 목표에 맞는 지표 집합을 함께 계산해야 한다.","bad":true},{"txt":"예측 시간·모델 크기 같은 운영 지표가 없다. 배포 판단에는 이것도 필요하다.","bad":true},{"txt":"평가 대상 데이터의 크기·분포·기간을 기록하지 않아 나중에 수치를 재현·비교할 수 없다.","bad":true},{"txt":"평가 함수가 딕셔너리를 반환하면 지표 추가가 불가능해지므로 클래스로 만들어야 한다.","bad":false},{"txt":"accuracy_score 는 모든 문제 유형에 적용되므로 지표 선택이 불필요하다.","bad":false},{"txt":"model.predict 를 평가 함수 안에서 호출하면 부수효과가 생겨 결과가 달라진다.","bad":false}],"ex":"결함 3가지: (1) 단일 지표. (2) 운영 지표 부재. (3) 평가 맥락 미기록. 디스트랙터: 딕셔너리는 오히려 확장하기 쉽다. 정확도는 회귀·순위 문제에 쓸 수 없다. predict 는 순수 함수에 가깝다."}],"th":{"sum":"평가 리뷰의 질문은 세 개다: **이 지표가 목표를 반영하는가 · 이 수치를 믿을 만한가 · 이 세트를 몇 번 들여다봤는가.**","body":[{"h":"지표가 목표를 반영하는가","t":"불균형에서 정확도는 정보가 없고, ROC-AUC 도 낙관적으로 보인다(PR-AUC 를 함께). F1 은 오탐·미탐 비용을 같게 보고, R² 는 오차 크기를 말해 주지 않으며, MAPE 는 0 근처에서 터지고 비대칭이다. 클래스 가중치로 학습하면서 정확도로 평가하면 목표와 평가가 어긋난다. 그리고 어떤 수치든 기준선(다수 클래스·직전 값·인기 순)과 비교하지 않으면 좋은지 알 수 없다."},{"h":"이 수치를 믿을 만한가","t":"단일 수치에는 불확실성이 숨는다. 폴드별 표준편차·신뢰구간·표본 크기를 함께 보고하고, 유효 자릿수를 분산에 맞춘다. 표본 5개의 정밀도, 배치 하나의 손실, 최댓값 보고는 모두 없는 차이를 있는 것처럼 만든다. p 값만으로 결론을 내리면 표본이 큰 쪽이 항상 이긴다 — 효과 크기를 본다."},{"h":"이 세트를 몇 번 들여다봤는가","t":"테스트 세트로 하이퍼파라미터를 고르거나 조기 종료를 하거나 모델을 비교하면, 그 세트는 더 이상 미본 데이터가 아니다. 특성 조합 수천 개에서 최고를 고르면 우연히 높은 조합이 반드시 나온다(다중 비교). 선택은 검증으로, 보고는 테스트로 한 번만. 반복 탐색이 필요하면 중첩 교차검증을 쓴다."},{"h":"평균 하나로는 부족하다","t":"세그먼트별로 나누면 특정 사용자군에서 성능이 훨씬 나쁜 것이 드러난다. 학습·검증 곡선을 함께 그려야 편향과 분산을 구분할 수 있다. 확률을 사용자에게 보여 준다면 보정을 확인해야 하고, 배포 후에는 지연 라벨의 편향과 피드백 루프까지 고려해야 한다."}],"code":{"c":"# 결함: 불균형에 정확도 + 기본 임계값 + 테스트로 튜닝 + 단일 수치\nfor d in [3,5,7]:\n    m = fit(Xtr, ytr, depth=d)\n    a = accuracy_score(yte, m.predict(Xte))     # 양성 0.2% 인데 정확도\n    if a > best: best, bm = a, m\nprint(f\"{best:.4f}\")                             # 낙관적 + 과도한 자릿수\n\n# 고침: 목표 지표 · 검증으로 선택 · 임계값도 검증에서 · 불확실성 보고\ncv = StratifiedKFold(5, shuffle=True, random_state=42)\ngs = GridSearchCV(pipe, grid, cv=cv, scoring=\"average_precision\")\ngs.fit(Xtr, ytr)\ns = cross_val_score(gs.best_estimator_, Xtr, ytr, cv=cv, scoring=\"average_precision\")\nprint(f\"검증 PR-AUC {s.mean():.3f} ± {s.std():.3f}\")\n\npv = gs.predict_proba(Xval)[:,1]                # 임계값은 검증에서 고른다\nth = max(np.linspace(0.01,0.99,99), key=lambda t: fbeta_score(yval, pv>t, beta=2))\n\npt = gs.predict_proba(Xte)[:,1]                 # 테스트는 마지막 한 번\nprint(classification_report(yte, pt>th, digits=3))\nprint(\"기준선(다수):\", average_precision_score(yte, np.zeros_like(pt)))","cap":"선택은 검증에서, 보고는 테스트에서 한 번, 항상 기준선과 함께"},"key":["불균형에 정확도 금지. 목표에 맞는 지표를 먼저 정하고 기준선과 비교한다","임계값 0.5 는 기본값일 뿐이고, 임계값은 검증 세트에서 고른다","테스트 세트로 튜닝·조기 종료·모델 비교를 하면 그 수치는 낙관적이다","평균만 보고하지 않는다 — 표준편차·신뢰구간·표본 크기, 자릿수는 분산에 맞춘다","p 값만으로 결론 내지 않는다. 효과 크기와 다중 비교 보정을 함께 본다","세그먼트별·확률 보정·배포 후 지연 라벨의 편향까지 본다"]}}]}]);
